import { KnowledgeItem } from '../../types';

/**
 * SOCCER_CORPUS_EXPANSION — a large dedicated football (soccer) knowledge base,
 * requested by Patrick (a massive soccer fan and FC Barcelona supporter). 130+
 * keyword-dense entries: World Cups, the Champions League, the major domestic
 * leagues, a deep FC Barcelona section, players and the GOAT debate, managers,
 * tactics, rules and officiating, positions and roles, records and lore, and
 * the transfer market. Additive to footballIntelligence.ts (kept untouched).
 */
const now = Date.now();
const k = (
  id: string,
  title: string,
  keywords: string[],
  content: string
): KnowledgeItem => ({ id, title, category: 'soccer', keywords, content, createdAt: now });

export const SOCCER_CORPUS_EXPANSION: KnowledgeItem[] = [
  // ===================== THE GAME, BASICS, LAWS =====================
  k('kb-soc-what-is-football', 'What football (soccer) is', ['what is football', 'soccer basics', 'association football', 'rules of soccer', '11 players', '90 minutes', 'two halves', 'goal'], `Association football (called "football" in most of the world, "soccer" in North America and Australia) is a team sport played 11 v 11 on a rectangular grass or artificial pitch, over two 45-minute halves plus stoppage time. Outfield players may use any part of the body except the arms and hands to move the ball; only the goalkeeper may handle it, and only inside his own penalty area. A goal is scored when the whole ball crosses the whole goal line between the posts and under the bar. The team with more goals wins; many league games can end in a draw (1 point each, 3 for a win). The sport is governed worldwide by FIFA, its 17 "Laws of the Game" are maintained by IFAB, and it is by far the most popular sport on earth, with the World Cup final watched by roughly a billion people.`),
  k('kb-soc-offside-law', 'The offside law explained', ['offside rule', 'offside law 11', 'second last defender', 'level is onside', 'active involvement', 'interfering with play', 'passive offside', 'flag delay'], `A player is in an OFFSIDE POSITION if, at the moment a teammate plays the ball, he is in the opponent's half AND nearer to the opponent's goal line than both the ball and the second-last opponent (usually the last outfield defender, since the keeper is normally the last). Being level with that defender or with the ball is ONSIDE. An offside position is only an offence if the player then becomes involved in active play — receiving the ball, challenging an opponent for it, or gaining an advantage from a rebound or deflection. You cannot be offside from a throw-in, corner or goal kick, or when in your own half. Assistant referees keep the flag down until the phase of play resolves ("wait and see") so a wrong early flag does not kill a legitimate goal; VAR checks tight calls with calibrated offside lines.`),
  k('kb-soc-handball-law', 'Handball in football', ['handball rule', 'deliberate handball', 'unnaturally bigger', 'arm above shoulder', 'accidental handball goal', 'attacking handball', 'silhouette'], `Handball is contacting the ball with the hand or arm up to the bottom of the armpit. It is an offence if the player deliberately touches the ball, OR makes his body "unnaturally bigger" with the arm (arm away from the body, not a consequence of the movement), OR scores directly with hand/arm, OR scores or creates a goalscoring chance immediately after the ball has touched his own hand/arm even accidentally. It is NOT an offence if the ball comes off the player's own body or a nearby teammate first, if the arm is close to the body supporting a fall, or (for non-scoring situations) if the contact is purely accidental. Goalkeepers handling outside their area, or handling a deliberate back-pass or throw-in from a teammate, are also penalised (indirect free kick).`),
  k('kb-soc-var', 'VAR (Video Assistant Referee)', ['VAR', 'video assistant referee', 'clear and obvious error', 'four reviewable decisions', 'on-field review', 'offside lines', 'semi-automated offside'], `VAR, introduced to the World Cup in 2018, lets video officials review the on-field referee's decisions in four match-changing categories only: goals (and the build-up), penalty decisions, direct red cards, and mistaken identity. The threshold for intervention is a "clear and obvious error" or a "serious missed incident"; VAR is not meant to re-referee every call. The VAR recommends, and the referee can either accept it or view the pitchside monitor for an "on-field review" and decide himself. Offside is checked with calibrated lines; "semi-automated offside" (from 2022) uses limb-tracking cameras and a sensor in the ball to speed this up. VAR has cut some clear injustices but is criticised for long delays, killing goal celebrations, and inconsistent handball and offside-by-a-toe rulings.`),
  k('kb-soc-cards-fouls', 'Fouls, free kicks and cards', ['yellow card', 'red card', 'direct free kick', 'indirect free kick', 'penalty kick', 'caution', 'sending off', 'two yellows', 'DOGSO', 'advantage'], `A foul is an unfair physical act against an opponent (kicking, tripping, pushing, holding, a reckless or careless challenge). Most fouls give the other team a DIRECT free kick (or a PENALTY if committed by the defending team inside its own penalty area) — a direct free kick can be scored straight into the goal. Technical offences (offside, obstruction, dangerous play, keeper handling a back-pass) give an INDIRECT free kick, which must touch another player before a goal counts. A YELLOW card (caution) is for unsporting behaviour, dissent, persistent fouling, delaying the restart or reckless challenges; two yellows in a match equal a RED. A straight RED (sending-off, and the team plays a man short for the rest of the game) is for serious foul play, violent conduct, spitting, a deliberate handball or foul that denies an obvious goalscoring opportunity (DOGSO), or offensive language. The referee can play ADVANTAGE, letting play continue if the fouled team benefits.`),
  k('kb-soc-restarts', 'Restarts: throw-in, corner, goal kick, drop ball', ['throw-in', 'corner kick', 'goal kick', 'kick-off', 'drop ball', 'set piece restarts', 'both feet on the ground throw'], `Play is restarted from a dead ball in set ways. Kick-off starts each half and follows a goal. A THROW-IN is awarded when the ball fully crosses a touchline; it is thrown with both hands, from behind and over the head, with both feet on or behind the line touching the ground. When the ball crosses the goal line (not into the goal) off a DEFENDER, the attacking team gets a CORNER KICK from the quadrant; off an ATTACKER, the defending team gets a GOAL KICK from anywhere in the six-yard box (since 2019 the ball is in play immediately and can be received inside the area). A DROP BALL restarts play after a stoppage for an injury or outside interference, given to the team that last touched it, with opponents 4m away.`),
  k('kb-soc-extra-time-pens', 'Extra time, penalty shootouts and golden goal', ['extra time', 'penalty shootout', 'golden goal', 'silver goal', 'sudden death', 'best of five penalties', 'away goals abolished'], `In knockout matches level after 90 minutes, most competitions play EXTRA TIME: two 15-minute halves, played in full (no golden goal now). If still level, a PENALTY SHOOTOUT decides it: each team takes five kicks, alternating, from the penalty spot; the team with more scored wins, and if still tied it goes to sudden death (one pair of kicks at a time). GOLDEN GOAL (1993-2004) ended the match the instant a goal was scored in extra time; SILVER GOAL (2002-04) ended it at the next half-time if a team led. Both were scrapped for making teams too cautious. UEFA ABOLISHED the away-goals tiebreaker from 2021-22, so a two-legged tie level on aggregate now always goes to extra time and penalties.`),

  // ===================== WORLD CUP =====================
  k('kb-soc-wc-overview', 'FIFA World Cup: overview and format', ['World Cup', 'FIFA World Cup', 'every four years', '32 teams', '48 teams 2026', 'group stage knockout', 'host qualifies automatically', 'trophy'], `The FIFA World Cup, first held in Uruguay in 1930, is the biggest single-sport event on earth, contested by national men's teams every four years. From 1998 to 2022 it had 32 teams: eight groups of four (round-robin, top two advance), then a straight knockout from the round of 16 to the final. From 2026 it expands to 48 teams (12 groups of four, with 24 of 32 advancing to a round of 32) co-hosted by the USA, Canada and Mexico; the 2030 centenary edition is spread across Spain, Portugal and Morocco with opening games in Uruguay, Argentina and Paraguay. Brazil have won it a record five times; only eight nations have ever won: Brazil, Germany, Italy (4 each), Argentina, France, Uruguay, England and Spain.`),
  k('kb-soc-wc-2022', 'World Cup 2022 (Qatar) and the Lusail final', ['World Cup 2022', 'Qatar', 'Argentina Messi', 'Mbappe hat-trick', 'Lusail final', '3-3 penalties', 'greatest final ever', 'winter World Cup'], `Qatar 2022 was the first World Cup in the Middle East and the first held in November-December (to avoid the desert summer). Argentina, led by Lionel Messi in his fifth and final World Cup, lost their opener 2-1 to Saudi Arabia and then won everything else. The final against France at the Lusail Stadium is widely called the greatest ever: Argentina led 2-0 (Messi penalty, Di Maria), France equalised through a Kylian Mbappe penalty and volley within 97 seconds late on, Messi scored in extra time, Mbappe completed a hat-trick with another penalty for 3-3, and Argentina won the shootout 4-2, Emiliano Martinez saving and Montiel converting the winner. Messi finally lifted the trophy and won the Golden Ball; Mbappe won the Golden Boot with 8 goals.`),
  k('kb-soc-wc-1986-2014', 'Iconic World Cups: 1986, 1998, 2010, 2014', ['World Cup 1986 Maradona', 'Hand of God', 'goal of the century', 'World Cup 1998 France Zidane', 'World Cup 2010 Spain', 'World Cup 2014 Germany 7-1 Brazil'], `1986 Mexico: Diego Maradona almost single-handedly won it for Argentina, most famously in the quarter-final against England where he scored the "Hand of God" (a punched goal the referee missed) and then, minutes later, the "Goal of the Century", dribbling from his own half past five players. 1998 France: hosts France won their first title, Zinedine Zidane scoring twice with headers in a 3-0 final defeat of Brazil (whose star Ronaldo had a mysterious pre-match fit). 2010 South Africa: Spain, playing tiki-taka under Vicente del Bosque, won their first World Cup, Andres Iniesta scoring the only goal of a bad-tempered final v the Netherlands. 2014 Brazil: Germany humiliated the hosts 7-1 in the semi-final (5-0 up inside 29 minutes) and beat Argentina 1-0 in the final through a Mario Gotze extra-time volley.`),
  k('kb-soc-wc-records', 'World Cup records', ['World Cup records', 'Klose 16 goals', 'Just Fontaine 13 in one tournament', 'Matthaus most appearances', 'Brazil 5 titles', 'Pele 3 winners medals', '1950 Maracanazo'], `All-time World Cup top scorer: Miroslav Klose (Germany), 16 goals across four tournaments. Most goals in a single edition: Just Fontaine (France), 13 in 1958. Most tournaments played: Lothar Matthaus (Germany) and Antonio Carbajal / Rafael Marquez (Mexico) and Messi and Ronaldo, all with 5. Only player with three winners' medals: Pele (Brazil, 1958, 1962, 1970). Youngest scorer: Pele, 17, in 1958. Biggest final crowd: about 174,000 (some say 199,000) at the Maracana for the 1950 decider, where Uruguay stunned Brazil 2-1 (the "Maracanazo"). Fastest goal: Hakan Sukur, 11 seconds, 2002. Biggest win: Hungary 10-1 El Salvador, 1982.`),

  // ===================== CHAMPIONS LEAGUE / EUROPE =====================
  k('kb-soc-ucl-overview', 'UEFA Champions League: history and format', ['Champions League', 'European Cup', 'UEFA', 'Big Ears trophy', 'group stage', 'league phase 2024', 'anthem', 'Real Madrid 15 titles'], `The UEFA Champions League is the top club competition in Europe (and, by strength of field, the world), evolved from the European Cup founded in 1955. Real Madrid dominate the roll of honour with 15 titles (including the first five in a row, 1956-60), ahead of Milan (7), Liverpool and Bayern Munich (6), and Barcelona (5). Clubs qualify by league position; the reigning champions also enter. From 2024-25 the old 32-team, eight-group format was replaced by a single 36-team "league phase" in which each club plays eight different opponents, with the top eight going straight to the last 16 and teams 9-24 playing a two-legged play-off. The Tony Britten anthem, sung before every game, is based on Handel's "Zadok the Priest".`),
  k('kb-soc-ucl-finals', 'Legendary Champions League finals', ['Istanbul 2005 Liverpool Milan', 'Miracle of Istanbul', 'Manchester United 1999 Camp Nou', 'Fergie time', 'Chelsea 2012 Munich', 'Real Madrid La Decima 2014'], `1999, Camp Nou: Manchester United, 1-0 down to Bayern Munich, scored twice in stoppage time through substitutes Sheringham and Solskjaer to complete the Treble ("football, bloody hell"). 2005, Istanbul: Liverpool were 3-0 down to AC Milan at half-time, scored three times in six second-half minutes (Gerrard, Smicer, Alonso), and won on penalties with Jerzy Dudek's saves — "The Miracle of Istanbul". 2012, Munich: Chelsea beat Bayern in their own stadium, Drogba equalising with a late header and scoring the winning penalty. 2014, Lisbon: Real Madrid's "La Decima" — Sergio Ramos headed a 93rd-minute equaliser against Atletico Madrid and Real ran out 4-1 winners in extra time, starting a run of four titles in five years under Zidane.`),
  k('kb-soc-europa-conference', 'Europa League and Conference League', ['Europa League', 'UEFA Cup', 'Sevilla seven titles', 'Conference League', 'third tier', 'winner gets a Champions League place'], `The UEFA Europa League (formerly the UEFA Cup, rebranded 2009) is Europe's second-tier club competition. Clubs qualify by finishing just below the Champions League places or by winning a domestic cup; some clubs also drop in from the Champions League. Since 2015 the Europa League winners earn a place in the next Champions League. Sevilla have made it their own with a record seven titles (2006-2023). The UEFA Europa Conference League, launched in 2021 and renamed the UEFA Conference League, is a third tier giving clubs from smaller nations regular European football; its winner is promoted to the Europa League. West Ham (2023) and Chelsea (2025) are among the early winners.`),

  // ===================== DOMESTIC LEAGUES =====================
  k('kb-soc-premier-league', 'The Premier League (England)', ['Premier League', 'EPL', 'English top flight', 'Manchester City dynasty', 'richest league', '20 clubs', 'Big Six', 'relegation to Championship'], `The Premier League, formed in 1992 when the old First Division clubs broke away for TV money, is the richest and most-watched domestic league in the world, played by 20 clubs with the bottom three relegated to the Championship. Manchester United dominated the early decades under Sir Alex Ferguson (13 titles); more recently Manchester City, backed by Abu Dhabi ownership and managed by Pep Guardiola, have won it in most seasons since 2017, including four in a row (2021-2024) and the 2023 Treble. Arsenal's 2003-04 "Invincibles" went a whole 38-game season unbeaten. Leicester City's 5000-1 title in 2015-16 is the greatest shock in sports betting history. The "Big Six" are Manchester United, Manchester City, Liverpool, Arsenal, Chelsea and Tottenham.`),
  k('kb-soc-la-liga', 'La Liga (Spain)', ['La Liga', 'Spanish league', 'Primera Division', 'Real Madrid Barcelona duopoly', 'El Clasico', 'Atletico Madrid', 'Athletic Bilbao Basque-only'], `La Liga is Spain's top division, historically a duopoly of Real Madrid (record 36 titles) and Barcelona (27), with Atletico Madrid the persistent third force under Diego Simeone (2014, 2021). The two-legged, sometimes twice-yearly meeting of Madrid and Barcelona, El Clasico, is the biggest club fixture in world football. La Liga produced the tiki-taka era: Barcelona under Pep Guardiola (2008-2012) and Spain's 2008-2012 international dominance. Athletic Club de Bilbao famously field only Basque players. Recent seasons have seen the balance shift as Barcelona's finances forced sales and Real Madrid rebuilt around Vinicius, Bellingham and Mbappe.`),
  k('kb-soc-serie-a', 'Serie A (Italy)', ['Serie A', 'Italian league', 'Juventus nine in a row', 'Milan Inter', 'catenaccio', 'Calciopoli scandal', 'Scudetto'], `Serie A, Italy's top flight, was the strongest league in the world in the late 1980s and 1990s, when Italian clubs bought the best players and AC Milan (Sacchi, Capello), Juventus and Internazionale dominated Europe. Juventus have the most titles (36 Scudetti, though two were stripped in the 2006 Calciopoli match-fixing scandal that also relegated them for one season). Juventus then won nine consecutive league titles from 2012 to 2020. Italian football is associated with tactical discipline and defending — the catenaccio ("door-bolt") tradition — and with legendary defenders like Franco Baresi, Paolo Maldini and Fabio Cannavaro. Napoli's 2023 title, their first since Maradona in 1990, ended a long wait.`),
  k('kb-soc-bundesliga-ligue1', 'Bundesliga (Germany) and Ligue 1 (France)', ['Bundesliga', 'Bayern Munich dominance', 'Borussia Dortmund Yellow Wall', '50+1 rule', 'Ligue 1', 'PSG QSI', 'Der Klassiker'], `The Bundesliga is Germany's top league, famous for the highest average attendances in world football, cheap tickets, standing terraces, and the "50+1" rule that keeps members in majority control of clubs. Bayern Munich have utterly dominated, winning eleven straight titles from 2013 to 2023 before Bayer Leverkusen's unbeaten "Neverkusen" title in 2024 under Xabi Alonso. Borussia Dortmund, with the huge "Yellow Wall" terrace, are Bayern's main rivals (Der Klassiker). Ligue 1 is France's top division; since the Qatari QSI takeover of Paris Saint-Germain in 2011, PSG have won it almost every year, signing Ibrahimovic, Neymar, Mbappe and Messi, and finally won the Champions League in 2025 under Luis Enrique with a young, homegrown-leaning squad.`),
  k('kb-soc-other-leagues', 'Eredivisie, Primeira Liga, MLS and South America', ['Eredivisie Ajax', 'Total Football', 'Primeira Liga Porto Benfica Sporting', 'MLS Messi Inter Miami', 'Brazilian Serie A', 'Argentine Primera'], `The Dutch Eredivisie is a famous talent factory: Ajax's academy and philosophy gave the world Total Football, Cruyff, and generations of stars, and Ajax won the 1995 Champions League with a very young side. Portugal's Primeira Liga is dominated by Porto, Benfica and Sporting CP, all elite selling clubs (Porto won the Champions League under Mourinho in 2004). Major League Soccer (MLS) in the USA and Canada, with no relegation and a salary cap and "designated player" slots, grew hugely after Lionel Messi joined Inter Miami in 2023 and won the Leagues Cup. In South America, Brazil's Serie A and Argentina's Primera feed players to Europe, while the Copa Libertadores is the continent's Champions League equivalent (Boca Juniors and River Plate the biggest names).`),

  // ===================== FC BARCELONA (deep) =====================
  k('kb-soc-barca-history', 'FC Barcelona: history and identity', ['FC Barcelona', 'Barca', 'Blaugrana', 'Mes que un club', 'founded 1899', 'Joan Gamper', 'Camp Nou', 'Catalan identity', 'socis members'], `FC Barcelona, founded in 1899 by the Swiss Joan Gamper, is one of the biggest clubs in the world and a symbol of Catalan identity — its motto is "Mes que un club" ("More than a club"). It is owned by its ~140,000 members (socis), who elect the president. The team plays in blue and claret (blaugrana) at the Camp Nou (renamed Spotify Camp Nou), Europe's largest stadium (~99,000, expanding past 105,000 in the ongoing Espai Barca rebuild). During the Franco dictatorship the club was a vehicle for suppressed Catalan feeling, and it long refused shirt sponsorship, later carrying UNICEF for free. Barcelona have won La Liga 27 times and the European Cup / Champions League 5 times (1992, 2006, 2009, 2011, 2015).`),
  k('kb-soc-barca-cruyff', 'Cruyff, the Dream Team and the Barca philosophy', ['Johan Cruyff', 'Dream Team', 'Barcelona 1992 Wembley', 'La Masia', 'positional play', 'possession', 'Cruyff DNA', 'Romario Stoichkov'], `Johan Cruyff, a Dutch star player at Barcelona in the 1970s, returned as manager in 1988 and built the "Dream Team": Barcelona won four straight La Liga titles (1991-1994) and their first European Cup at Wembley in 1992 (a Ronald Koeman free kick), playing an attacking, possession-based 3-4-3 with Romario, Hristo Stoichkov, Michael Laudrup, Pep Guardiola and Txiki Begiristain. More importantly, Cruyff imposed a single playing identity from the first team down to the youth academy, La Masia — build from the back, keep the ball, press high, use the width, play through the lines — the "Cruyffismo" that still defines the club and produced Xavi, Iniesta, Messi, Busquets and Guardiola the coach.`),
  k('kb-soc-barca-pep-era', 'Pep Guardiola\'s Barcelona (2008-2012)', ['Pep Guardiola Barcelona', 'tiki-taka', 'Messi false 9', 'sextuple 2009', '2011 Wembley final', 'Xavi Iniesta Busquets', 'best team ever'], `Pep Guardiola took over Barcelona in 2008 and, with a spine of La Masia graduates (Xavi, Iniesta, Busquets, Messi, Pique, Pedro) plus Dani Alves and Eric Abidal, produced possibly the greatest club side ever. In his first season (2008-09) Barca won the "sextuple": La Liga, Copa del Rey, Champions League (2-0 v Manchester United in Rome), plus the Super Cup, Spanish Super Cup and Club World Cup. They beat United again in the 2011 final at Wembley in a masterclass. Guardiola turned Messi into a "false nine", dropping deep from centre-forward to overload midfield, and the team's tiki-taka — short passing, relentless pressing, positional discipline — dominated the world for four years.`),
  k('kb-soc-barca-msn-remontada', 'MSN and the 2017 Remontada', ['MSN Messi Suarez Neymar', 'treble 2015', 'Remontada', 'Barcelona 6-1 PSG', '6th March 2017', 'Sergi Roberto 95th minute', 'greatest comeback'], `Under Luis Enrique, Barcelona's front three of Lionel Messi, Luis Suarez and Neymar ("MSN") scored 122 goals in 2014-15 and won the treble (La Liga, Copa del Rey, Champions League, beating Juventus 3-1 in Berlin). Their most famous single night was 8 March 2017: 4-0 down from the first leg of a Champions League last-16 tie against PSG, Barcelona won the second leg 6-1 at the Camp Nou — "La Remontada" — scoring three times in the final seven minutes plus stoppage time, Neymar with two and an assist and Sergi Roberto poking in the winner in the 95th minute. It remains the only time a 4-0 first-leg deficit has been overturned in the competition.`),
  k('kb-soc-barca-clasico-moments', 'Barcelona in El Clasico: famous moments', ['El Clasico', 'Barcelona Real Madrid', 'Manita 5-0 2010', 'Guardiola 6-2 Bernabeu 2009', 'Messi shirt to the Bernabeu crowd 2017', 'Ronaldinho standing ovation 2005'], `El Clasico highs for Barcelona: the 6-2 win at the Santiago Bernabeu in May 2009 that broke Real Madrid and confirmed Guardiola's arrival; the 5-0 "manita" at the Camp Nou in November 2010 under Mourinho's Madrid; and Lionel Messi's stoppage-time winner at the Bernabeu in April 2017, after which he took off his shirt and held it up to the silenced home crowd — his 500th Barca goal. Ronaldinho earned a rare standing ovation from Bernabeu fans after a two-goal performance in 2005. Messi is the all-time top scorer in the fixture with 26 goals. The rivalry has produced some of the most-watched club matches in history, especially during the Messi-vs-Ronaldo decade.`),
  k('kb-soc-barca-la-masia', 'La Masia, Barcelona\'s academy', ['La Masia', 'Barcelona youth academy', 'Xavi Iniesta Messi Busquets Fabregas', 'positional play from age 6', '2010 Ballon d\'Or podium', 'Lamine Yamal Gavi Pedri'], `La Masia ("the farmhouse") is FC Barcelona's residential youth academy, one of the most productive in football. It trains every age group in the same Cruyffian style — technique, positional play, playing out from the back — so a graduate slots straight into the first team's system. In 2010 the entire Ballon d'Or podium (Messi, Iniesta, Xavi) were La Masia graduates, and in the 2011 Champions League final Barca started seven of them. The academy also produced Cesc Fabregas, Pedro, Pique, Thiago and Jordi Alba, and more recently Pedri, Gavi, Alejandro Balde, Fermin Lopez and Lamine Yamal, who debuted at 15 and became the youngest player and youngest scorer in many major competitions.`),
  k('kb-soc-barca-modern', 'Barcelona today: the Flick era and Lamine Yamal', ['Hansi Flick Barcelona', 'Lamine Yamal', 'Barcelona financial crisis', 'economic levers', 'Raphinha Lewandowski', 'high line offside trap', '2025 domestic treble'], `After years of financial crisis (huge wage bill, the forced Messi exit in 2021, selling future TV and licensing income via "economic levers" to register players), Barcelona rebuilt around cheap youth and a few signings. Under German coach Hansi Flick, hired in 2024, they play an aggressive, high-pressing, high-defensive-line game with a coordinated offside trap, and in 2024-25 won La Liga, the Copa del Rey and the Spanish Super Cup. Lamine Yamal, a right-winger from La Masia, is the face of the new era — Euro 2024 winner with Spain at 16, Kopa Trophy winner, and inheritor of the number 10 shirt — supported by Pedri and Gavi in midfield and Robert Lewandowski and Raphinha up front.`),

  // ===================== REAL MADRID / OTHER GIANTS =====================
  k('kb-soc-real-madrid', 'Real Madrid: the European Cup club', ['Real Madrid', 'Los Blancos', 'Merengues', '15 Champions League titles', 'Galacticos', 'Di Stefano Puskas', 'Santiago Bernabeu', 'La Quinta del Buitre'], `Real Madrid are the most successful club in European football, with a record 15 European Cup / Champions League titles and 36 La Liga titles. They won the first five European Cups (1956-1960) with Alfredo Di Stefano and Ferenc Puskas. Under president Florentino Perez they pursued the "Galacticos" policy, signing the biggest star each summer — Figo, Zidane, Ronaldo, Beckham, then later Cristiano Ronaldo, Bale, and Kylian Mbappe. Zidane the coach won three straight Champions Leagues (2016-2018). The club has an unmatched reputation for late European comebacks (the "remontadas" of 2022 against PSG, Chelsea and Manchester City on the way to the title). Home is the rebuilt, retractable-pitch Santiago Bernabeu.`),
  k('kb-soc-atletico-dortmund', 'Atletico Madrid and Borussia Dortmund', ['Atletico Madrid', 'Diego Simeone', 'Cholismo', 'defensive block', 'Wanda Metropolitano', 'Borussia Dortmund', 'Jurgen Klopp Dortmund', 'gegenpressing origins'], `Atletico Madrid, long in the shadow of Real, were transformed by Diego "Cholo" Simeone from 2011: "Cholismo" is a fiercely organised, low-block, counter-attacking style built on effort, defensive shape and set pieces. Atletico won La Liga in 2014 and 2021 and reached two Champions League finals (2014, 2016), both lost to Real Madrid. Borussia Dortmund, under Jurgen Klopp from 2008 to 2015, won two Bundesliga titles (2011, 2012) and reached the 2013 Champions League final with a young, high-energy "heavy metal football" side (Gotze, Reus, Lewandowski, Hummels) — the birthplace of modern gegenpressing before Klopp took it to Liverpool.`),

  // ===================== PLAYERS / GOAT =====================
  k('kb-soc-goat-debate', 'The GOAT debate: Messi, Ronaldo, Pele, Maradona', ['greatest of all time', 'Messi vs Ronaldo', 'Pele 1000 goals', 'Maradona 1986', 'Cruyff', 'Di Stefano', 'GOAT football'], `The "greatest of all time" argument usually centres on: Lionel Messi (8 Ballon d' Or, the 2022 World Cup, Barcelona's peak, universally rated the most gifted playmaker-scorer ever); Cristiano Ronaldo (5 Ballon d'Or, all-time top scorer in men's football with 900+, five Champions Leagues, unmatched longevity and athleticism); Pele (three World Cups, ~1280 career goals by his own count, the global icon of the sport); and Diego Maradona (the 1986 World Cup almost single-handed, Napoli's only two Scudetti, the "Hand of God" and "Goal of the Century"). Older voters add Johan Cruyff (revolutionised how football is played and coached) and Alfredo Di Stefano (five straight European Cups). There is no settled answer; Messi and Ronaldo defined 2008-2020.`),
  k('kb-soc-messi', 'Lionel Messi', ['Lionel Messi', 'Leo Messi', 'La Pulga', 'Argentina', 'Barcelona', 'Inter Miami', '8 Ballon d\'Or', '2022 World Cup', 'left foot'], `Lionel Andres Messi, born 1987 in Rosario, Argentina, moved to Barcelona's La Masia at 13 (the club paid for his growth-hormone treatment). He spent 2004-2021 at Barcelona, becoming its all-time top scorer (672 goals) and winning 4 Champions Leagues, 10 La Ligas and a record 8 Ballon d'Or awards, with a peak of 91 goals in the 2012 calendar year. A financial crisis forced his tearful exit to PSG in 2021, then Inter Miami in 2023. With Argentina he won the 2021 Copa America and, at last, the 2022 World Cup, plus the 2024 Copa America. A left-footed forward of extraordinary close control, balance, vision and finishing, he is regarded by most as the most complete attacking player in history.`),
  k('kb-soc-ronaldo-cr7', 'Cristiano Ronaldo', ['Cristiano Ronaldo', 'CR7', 'Portugal', 'Manchester United', 'Real Madrid', 'Juventus', 'Al-Nassr', 'all-time top scorer', 'Euro 2016'], `Cristiano Ronaldo dos Santos Aveiro, born 1985 in Madeira, Portugal, is the all-time leading goalscorer in men's football (900+ career, 130+ for Portugal) and in the Champions League (140+). He starred for Sporting, then Manchester United (2003-09, first Ballon d'Or, 2008 Champions League), then Real Madrid (2009-2018, four Champions Leagues, all-time club top scorer), then Juventus, a brief United return, and Al-Nassr in Saudi Arabia from 2023. He has won 5 Ballon d'Or awards, the 2016 European Championship and 2019 Nations League with Portugal, and is famous for his heading, right-foot power, free kicks, relentless physical conditioning and longevity into his 40s.`),
  k('kb-soc-classic-players', 'Cruyff, Beckenbauer, Di Stefano, Zidane', ['Johan Cruyff player', 'Cruyff turn', 'Franz Beckenbauer libero', 'Alfredo Di Stefano', 'Zinedine Zidane', '1998 2006 World Cup Zidane headbutt'], `Johan Cruyff (Netherlands, Ajax, Barcelona): the on-field brain of Total Football, 3 Ballon d'Or, inventor of the "Cruyff turn", and later the most influential coach in the game's history. Franz Beckenbauer ("Der Kaiser", West Germany, Bayern): redefined the sweeper (libero) role, won the World Cup as captain (1974) and manager (1990). Alfredo Di Stefano (Argentina/Spain, Real Madrid): the complete forward of the 1950s, scored in five consecutive European Cup finals. Zinedine Zidane (France, Juventus, Real Madrid): 1998 World Cup winner (two goals in the final), 2000 Euros, a Ballon d'Or, a sublime 2002 Champions League final volley — and a red card for headbutting Marco Materazzi in the 2006 final, his last act as a player.`),
  k('kb-soc-modern-stars', 'Modern stars: Mbappe, Haaland, Bellingham, Yamal', ['Kylian Mbappe', 'Erling Haaland', 'Jude Bellingham', 'Lamine Yamal', 'Vinicius Junior', 'Pedri', 'next generation'], `Kylian Mbappe (France): explosive forward, 2018 World Cup winner at 19, hat-trick in the 2022 final, joined Real Madrid in 2024. Erling Haaland (Norway): a giant, ruthless number 9 with record-breaking scoring rates at Dortmund and then Manchester City, where he won the 2023 Treble. Jude Bellingham (England): a complete midfielder, moved from Dortmund to Real Madrid in 2023 and immediately became their talisman. Lamine Yamal (Spain, Barcelona): a right-winger from La Masia, Euro 2024 winner and player of the tournament influence at 16, now the face of Barca's new era. Vinicius Junior (Brazil, Real Madrid) and Pedri (Spain, Barcelona) round out the group defining the post-Messi/Ronaldo era.`),
  k('kb-soc-midfield-greats', 'Midfield maestros', ['Xavi', 'Andres Iniesta', 'Sergio Busquets', 'Andrea Pirlo', 'Kevin De Bruyne', 'Luka Modric', 'Xabi Alonso', 'deep-lying playmaker'], `Xavi Hernandez: the metronome of Barcelona and Spain's tiki-taka, the definitive pass-and-move central midfielder, later Barca manager. Andres Iniesta: Barcelona's dribbling playmaker, scorer of the 2010 World Cup final goal and the 2009 semi-final winner at Chelsea. Sergio Busquets: the low-key defensive-midfield anchor who made everything work. Andrea Pirlo: the "regista" who dictated games from deep for Milan, Juventus and Italy. Luka Modric: Croatia's captain, 2018 Ballon d'Or, Real Madrid's long-serving orchestrator. Kevin De Bruyne: Manchester City's creative engine with elite passing and shooting. Xabi Alonso: a passing metronome for Liverpool, Real and Bayern, now an elite coach.`),
  k('kb-soc-strikers-keepers', 'Great strikers and goalkeepers', ['Ronaldo Nazario R9', 'Marco van Basten', 'Gerd Muller', 'Ibrahimovic', 'Lev Yashin', 'Gianluigi Buffon', 'Iker Casillas', 'Manuel Neuer'], `Strikers: Ronaldo Nazario ("R9", Brazil) — the fastest, most devastating centre-forward of his era before injuries, two-time World Cup winner and Golden Boot; Marco van Basten (Netherlands, Milan) — impossible technique, retired early through injury; Gerd Muller (West Germany, Bayern) — a penalty-box goal machine; Zlatan Ibrahimovic — huge, arrogant, acrobatic, prolific across seven top clubs. Goalkeepers: Lev Yashin (USSR) — the "Black Spider", the only keeper to win the Ballon d'Or; Gianluigi Buffon (Italy) — 2006 World Cup winner, played into his 40s; Iker Casillas (Spain, Real Madrid) — reflex saves and three straight international trophies; Manuel Neuer (Germany, Bayern) — the modern "sweeper-keeper".`),
  k('kb-soc-ballon-dor', 'The Ballon d\'Or', ['Ballon d\'Or', 'France Football', 'best player of the year', 'Messi 8', 'Ronaldo 5', 'Rodri 2024', 'Lewandowski robbed 2020', 'controversies'], `The Ballon d'Or, awarded by France Football since 1956, is the most prestigious individual prize in football, voted by journalists for the best player over a season. Lionel Messi has won a record 8, Cristiano Ronaldo 5, with three shared by Cruyff, Van Basten, Platini and Marco van Basten. Famous controversies: Wesley Sneijder (2010) winning nothing despite the treble with Inter and reaching the World Cup final; Franck Ribery (2013) losing to Ronaldo after Bayern's treble; the 2020 award being cancelled due to COVID, denying Robert Lewandowski in his best year; and Rodri (Manchester City) winning in 2024 ahead of Vinicius Junior, prompting Real Madrid to boycott the ceremony. The women's Ballon d'Or has been awarded since 2018.`),

  // ===================== MANAGERS =====================
  k('kb-soc-guardiola', 'Pep Guardiola', ['Pep Guardiola', 'positional play', 'juego de posicion', 'Barcelona Bayern Manchester City', '2023 Treble', 'inverted full-backs', 'possession pressing'], `Josep "Pep" Guardiola is the most influential coach of his generation. As a player he was Cruyff's on-pitch general at Barcelona. As a manager he won the treble with Barcelona (2009), three Bundesligas with Bayern Munich, and everything with Manchester City, including four straight Premier Leagues (2021-24) and the 2023 Treble. His football is built on "juego de posicion" (positional play): dominating the ball, occupying specific zones and half-spaces, creating numerical overloads, playing out from the goalkeeper, and pressing to win the ball back within five seconds. He has repeatedly reinvented tactics — the false nine, inverted full-backs stepping into midfield, a back three in possession — and his ideas now shape most elite coaching.`),
  k('kb-soc-ferguson-mourinho', 'Sir Alex Ferguson and Jose Mourinho', ['Sir Alex Ferguson', 'Manchester United', 'hairdryer treatment', 'Fergie time', 'Jose Mourinho', 'The Special One', 'Porto Chelsea Inter Real Madrid'], `Sir Alex Ferguson managed Manchester United from 1986 to 2013, winning 13 Premier Leagues, 2 Champions Leagues (1999 and 2008) and 38 trophies in total, famous for rebuilding successful teams repeatedly, man-management (and the "hairdryer treatment"), and late winners ("Fergie time"). Jose Mourinho, the "Special One", won the Champions League with unfancied Porto (2004) and with Inter Milan (2010, completing a treble with a masterful defensive semi-final against Barcelona), plus league titles at Porto, Chelsea (twice), Inter and Real Madrid. His style is pragmatic, defensively drilled, counter-attacking and confrontational — he thrives on a siege mentality and big single games more than on beautiful football.`),
  k('kb-soc-klopp-ancelotti-simeone', 'Klopp, Ancelotti, Simeone and other top managers', ['Jurgen Klopp Liverpool', 'heavy metal football', 'Carlo Ancelotti', 'five Champions Leagues coach', 'Diego Simeone Cholismo', 'Marcelo Bielsa'], `Jurgen Klopp: charismatic German, built gegenpressing sides at Mainz and Dortmund, then took Liverpool to the 2019 Champions League and their first league title in 30 years (2020) with a front three of Salah, Mane and Firmino and attacking full-backs. Carlo Ancelotti: the calm man-manager, a record five-time Champions League winner as coach (Milan x2, Real Madrid x3), league titles in all of Europe's big five. Diego Simeone: turned Atletico Madrid into a defensive, high-intensity juggernaut ("Cholismo"). Marcelo Bielsa ("El Loco"): the tactical purist and cult figure whose vertical, man-marking, all-action football influenced Guardiola, Pochettino and a generation, though he won few major trophies.`),
  k('kb-soc-total-football-sacchi', 'Total Football, Michels, Sacchi and Cruyff the coach', ['Total Football', 'Rinus Michels', 'Netherlands 1974', 'Arrigo Sacchi', 'AC Milan pressing zonal marking', 'Johan Cruyff coach', 'tactical lineage'], `Total Football, developed by Rinus Michels at Ajax and the Netherlands in the early 1970s, meant every outfield player could take over any position: constant rotation, relentless pressing, a compressed team shape and an aggressive offside trap. It reached the 1974 World Cup final (lost to West Germany). Cruyff carried it to Barcelona as a coach, adding a stricter positional structure. Arrigo Sacchi's late-1980s AC Milan (Baresi, Maldini, Gullit, Van Basten, Rijkaard) proved a defensive team could also press high and play zonal marking with a very high line, winning back-to-back European Cups. This Dutch-Italian lineage — Michels to Cruyff to Guardiola, and Sacchi's pressing — underlies almost all modern elite tactics.`),

  // ===================== TACTICS =====================
  k('kb-soc-formations', 'Football formations: 4-4-2, 4-3-3, 3-5-2 and more', ['4-4-2 formation', '4-3-3 formation', '3-5-2', '4-2-3-1', 'back three', 'diamond midfield', 'formation meaning'], `A formation describes how a team's ten outfield players are arranged, read from defence forward. The 4-4-2 (four defenders, four midfielders, two strikers) is the classic balanced shape, dominant from the 1980s to the 2000s. The 4-3-3 (three central midfielders, a winger each side, one striker) gives midfield control and width and is the modern default, used by Barcelona and most possession teams. The 4-2-3-1 adds a "double pivot" of two holding midfielders behind an attacking three. Back-three systems (3-5-2, 3-4-3) use wing-backs who defend as a five and attack as wingers. Formations are only a starting point — in possession and out of possession the same team may take completely different shapes.`),
  k('kb-soc-tikitaka', 'Tiki-taka and possession football', ['tiki-taka', 'possession football', 'short passing', 'positional play', 'Barcelona Spain', 'keep the ball to defend', 'triangles', 'rondo'], `Tiki-taka is the possession style perfected by Guardiola's Barcelona and Spain (2008-2012): a network of short, quick, one- and two-touch passes, players constantly moving to form passing triangles, dominating the ball to control the game (an opponent cannot score without it), and pressing immediately to win it back on loss. It grew out of Cruyff's ideas and the daily "rondo" (keep-ball drills). Its strengths are control, energy conservation and defensive protection; its weaknesses are being predictable against a disciplined low block and being vulnerable in transition if the counter-press fails. Later versions add more directness and verticality.`),
  k('kb-soc-pressing', 'Pressing, gegenpressing and the low block', ['pressing', 'high press', 'gegenpressing', 'counter-press', 'low block', 'mid block', 'pressing triggers', 'compact shape'], `Pressing is closing down opponents to force errors and win the ball high up the pitch. A HIGH PRESS starts near the opponent's goal; a MID or LOW BLOCK sits deeper, staying compact and conceding possession to protect space. GEGENPRESSING (counter-pressing) is a specific idea popularised by Klopp: the moment you lose the ball, immediately swarm it — the opponent is unbalanced and closest to their own goal, so winning it back there is the best attacking chance ("the best playmaker is a turnover"). Effective pressing needs "triggers" (a bad touch, a backward pass, a sideline), coordinated movement so one press is not bypassed, and the fitness to sustain it. It is high-risk: if broken, the team is exposed.`),
  k('kb-soc-catenaccio-counter', 'Catenaccio and counter-attacking football', ['catenaccio', 'door bolt', 'Italian defending', 'libero sweeper', 'counter-attack', 'low block', 'Helenio Herrera Inter', 'transition football'], `Catenaccio ("door-bolt") is the Italian defensive system of the 1960s, associated with Helenio Herrera's Inter Milan: a tight man-marking back line with a free "libero" (sweeper) behind it to mop up, absorbing pressure and then striking fast on the break. Modern counter-attacking football keeps the same spirit without the sweeper: defend deep and compact in a "low block", stay disciplined, then transition forward very quickly with a handful of passes and pacey forwards the instant possession is won, before the opponent can reset. Leicester's 2016 title, Simeone's Atletico, and many of Mourinho's biggest wins were built this way — it is especially effective against dominant possession teams.`),
  k('kb-soc-false-nine-roles', 'The false nine and other attacking roles', ['false nine', 'Messi false 9', 'target man', 'poacher', 'inside forward', 'winger', 'second striker', 'trequartista'], `A FALSE NINE is a centre-forward who drops deep into midfield instead of leading the line, dragging a centre-back out (creating space in behind for runners) or leaving him with no one to mark (a spare man for the false nine to receive between the lines). Guardiola used Messi there. A TARGET MAN is a big striker who holds the ball up, wins headers and brings others into play. A POACHER lives in the box and finishes. An INSIDE FORWARD is a winger who cuts inside onto his stronger foot to shoot (a left-footer on the right). A SECOND STRIKER / TREQUARTISTA / number 10 plays just behind the main striker, linking midfield and attack.`),
  k('kb-soc-inverted-fullback', 'Inverted full-backs, overloads and half-spaces', ['inverted full-back', 'full-back into midfield', 'half-spaces', 'zone 14', 'overload to isolate', 'third-man run', 'positional play zones'], `Modern positional play divides the pitch into vertical channels; the "half-spaces" (between the centre and the wing) are the most dangerous zones to receive because a player there can see the whole pitch and threaten goal. "Zone 14" is the central area just outside the box where most chances are created. An INVERTED FULL-BACK steps infield into central midfield in possession (rather than overlapping down the touchline), giving an extra passer, protecting against counter-attacks, and freeing a winger to stay wide and one-v-one. "Overload to isolate" means packing players on one side to draw defenders across, then quickly switching to a winger left one-v-one on the far side. A "third-man run" is a pass to a first player who lays it to a second, releasing a third arriving into space.`),
  k('kb-soc-set-pieces', 'Set-piece play', ['set pieces', 'corner routines', 'free kick', 'wall', 'near-post flick', 'zonal versus man marking corners', 'set-piece coach', 'throw-in specialist'], `Set pieces (corners, free kicks, penalties, long throws) produce roughly a third of goals at the top level, so clubs now employ dedicated set-piece coaches. Attacking routines include near-post flick-ons, blocking runs ("picks") to free a target, short corners to change the angle, and rehearsed free-kick decoys. Defending a corner is done zonally (each defender guards a space and attacks any ball in it), man-to-man (each marks an opponent), or a hybrid. A defensive wall lines up to cover one side of the goal for a direct free kick, with the keeper covering the other. Long-throw specialists (Rory Delap, Stoke) can turn a throw-in into a corner-like threat.`),

  // ===================== POSITIONS =====================
  k('kb-soc-goalkeeper', 'The goalkeeper', ['goalkeeper', 'keeper', 'shot-stopping', 'distribution', 'commanding the area', 'sweeper-keeper', 'number 1', 'clean sheet'], `The goalkeeper is the only player allowed to handle the ball, and only inside his own penalty area. Core duties: stopping shots (positioning, reflexes, one-v-ones), dealing with crosses and set pieces (claiming or punching), organising the defence, and distributing the ball (throws, short passes, long kicks). The modern goalkeeper must also be a "sweeper-keeper": starting higher to cover space behind a high defensive line and comfortable receiving back-passes under pressure to help the team play out. A "clean sheet" (no goals conceded) is the keeper's headline stat. Great keepers combine shot-stopping with command of the box and calm feet; a keeper error near his own goal is one of the most costly mistakes in the game.`),
  k('kb-soc-defenders', 'Defenders: centre-backs and full-backs', ['centre-back', 'central defender', 'ball-playing defender', 'full-back', 'wing-back', 'overlapping run', 'defensive line', 'stepping up offside trap'], `CENTRE-BACKS (two, sometimes three) defend the middle: heading, tackling, blocking, marking strikers, and holding the defensive line (stepping up together to play opponents offside). A "ball-playing" centre-back also starts attacks with progressive passes. FULL-BACKS play wide in a back four: they defend against wingers and also join the attack with "overlapping" runs down the touchline to cross or "underlapping" runs inside. WING-BACKS, used in a back three, are essentially wingers who track all the way back to make a defensive five — they need huge stamina. Full-backs have become one of the most attacking positions in the modern game (Alves, Alexander-Arnold, Cancelo).`),
  k('kb-soc-midfielders', 'Midfielders: defensive, central and attacking', ['defensive midfielder', 'holding midfielder', 'pivot', 'regista', 'destroyer', 'box-to-box', 'attacking midfielder', 'number 10', 'creative hub'], `DEFENSIVE MIDFIELDERS (the "6", "pivot", "anchor") shield the back four, break up attacks, and recycle possession — sub-types are the "destroyer" (Kante, tackling and covering) and the "regista" (Pirlo, Busquets, dictating from deep). CENTRAL MIDFIELDERS (the "8") do a bit of everything; a "box-to-box" 8 (Vieira, Gerrard, Bellingham) covers the whole pitch, defending and arriving late in the attacking box. ATTACKING MIDFIELDERS (the "10", trequartista) play between the opposition's midfield and defence, receiving in pockets to create chances with vision and passing. Modern midfields are usually a three: one holder plus two more mobile 8s, or a double pivot behind a 10.`),
  k('kb-soc-wingers-forwards', 'Wingers and forwards', ['winger', 'wide forward', 'inverted winger', 'inside forward', 'striker', 'centre-forward', 'number 9', 'target man', 'poacher', 'complete forward'], `WINGERS play wide in attack: a traditional winger stays on the touchline to beat a full-back and cross with his stronger, same-side foot; an INVERTED WINGER / INSIDE FORWARD plays on the "wrong" side (a right-footer on the left) so he can cut inside onto his stronger foot to shoot or combine, with an overlapping full-back providing the width. The STRIKER / CENTRE-FORWARD (the "9") is the main goal threat: a POACHER finishes in the box, a TARGET MAN holds the ball up and wins headers, a COMPLETE FORWARD (Benzema, Lewandowski) does both plus link play, and a FALSE NINE drops into midfield. A SECOND STRIKER plays off the main 9. Teams line up with one striker and two wingers (4-3-3) or two strikers (4-4-2).`),

  // ===================== RECORDS, LORE, MOMENTS =====================
  k('kb-soc-leicester-2016', 'Leicester City\'s 2015-16 Premier League title', ['Leicester City 5000-1', 'greatest sporting shock', 'Claudio Ranieri', 'Jamie Vardy Riyad Mahrez Kante', 'counter-attacking champions'], `Leicester City, who had barely survived relegation the previous season and were 5000-1 outsiders with the bookmakers, won the 2015-16 Premier League under Claudio Ranieri. They played a compact, hard-working, counter-attacking 4-4-2, built on Kasper Schmeichel in goal, N'Golo Kante covering every blade of grass in midfield, Riyad Mahrez's dribbling, and Jamie Vardy's runs in behind (Vardy scored in a record 11 consecutive games). None of the traditional "Big" clubs mounted a serious challenge. It is universally regarded as the greatest shock in the history of team sport, and the last time an outsider has broken the elite's grip on a major European league.`),
  k('kb-soc-aguero-9320', 'Aguero 93:20 — the 2012 Premier League finish', ['Aguerooooo', 'Manchester City 2012 title', '93:20', 'QPR 3-2', 'Manchester United United minute', 'Martin Tyler commentary'], `On the final day of the 2011-12 season, Manchester City needed to beat QPR at home to win their first league title in 44 years, or Manchester United (already finished, top on goal difference) would take it. City were 2-1 down with 90 minutes gone. Edin Dzeko headed an equaliser in the 92nd minute, and in the 94th (clock reading 93:20) Sergio Aguero collected a pass, played a one-two, cut inside and smashed the winner low into the corner. Martin Tyler's scream of "Agueroooooo!" is the most famous piece of English football commentary. It also denied United the title in Sir Alex Ferguson's penultimate season.`),
  k('kb-soc-istanbul-2005', 'Istanbul 2005 and the corner taken quickly', ['Miracle of Istanbul', 'Liverpool 3-3 AC Milan 2005', 'Steven Gerrard', 'Jerzy Dudek save', 'Origi corner Barcelona 2019 4-0'], `In the 2005 Champions League final in Istanbul, Liverpool were 3-0 down to AC Milan at half-time. In six second-half minutes they scored three: a Steven Gerrard header, a Vladimir Smicer strike, and a Xabi Alonso penalty rebound. Extra time was scoreless; goalkeeper Jerzy Dudek made a double save from Shevchenko and then his "spaghetti legs" antics helped Liverpool win the shootout. In 2019 Liverpool produced another miracle at Anfield: 3-0 down from the first leg of the semi-final against Barcelona, they won 4-0, the fourth goal coming when Trent Alexander-Arnold spotted the Barca defence napping and took a corner quickly for Divock Origi to finish — "Corner taken quickly... ORIGI!".`),
  k('kb-soc-invincibles-class92', 'Arsenal\'s Invincibles and United\'s Class of \'92', ['Arsenal Invincibles 2003-04', 'unbeaten season', 'Thierry Henry', 'Manchester United Class of 92', 'Beckham Scholes Giggs Neville Butt'], `Arsenal's "Invincibles" of 2003-04, under Arsene Wenger, went the entire 38-game Premier League season unbeaten (26 wins, 12 draws), the only side to do so in the 20-club era, built around Thierry Henry, Dennis Bergkamp, Patrick Vieira and a back line marshalled by Sol Campbell. Manchester United's "Class of '92" was a golden generation of academy graduates — David Beckham, Paul Scholes, Ryan Giggs, Gary and Phil Neville, Nicky Butt — who broke into the first team together and were the core of the club's success under Ferguson for over a decade, including the 1999 Treble. Alan Hansen's line "you can't win anything with kids" became infamous when they won the double that year.`),
  k('kb-soc-derbies', 'The great derbies and rivalries', ['El Clasico', 'Superclasico Boca River', 'Old Firm Celtic Rangers', 'Derby della Madonnina Milan Inter', 'North London derby', 'Merseyside derby', 'Der Klassiker'], `The biggest club rivalries: El Clasico (Real Madrid v Barcelona) — the most-watched club fixture in the world; the Superclasico (Boca Juniors v River Plate) in Buenos Aires — often rated the most intense atmosphere in football; the Old Firm (Celtic v Rangers) in Glasgow, with a sectarian edge; the Derby della Madonnina (AC Milan v Inter), who share the San Siro; the North London derby (Arsenal v Tottenham); the Merseyside derby (Everton v Liverpool); the Manchester derby (United v City); Der Klassiker (Bayern v Dortmund); the Eternal Derby (Red Star v Partizan, Belgrade); and Fenerbahce v Galatasaray in Istanbul. A "derby" strictly means two clubs from the same city or region; a rivalry can span a whole country.`),
  k('kb-soc-immortal-moments', 'Immortal World Cup and football moments', ['Carlos Alberto 1970 goal', 'Maradona goal of the century', 'Roberto Baggio penalty miss 1994', 'Zidane headbutt 2006', 'Iniesta 2010', 'Ghost goal Frank Lampard 2010'], `Carlos Alberto's team goal to finish the 4-1 1970 final (Brazil's greatest team). Maradona's solo run past five England players in 1986. Roberto Baggio blazing the decisive penalty over the bar in the 1994 final shootout. Zidane's headbutt on Materazzi in the 2006 final. Andres Iniesta's winning goal for Spain in the 2010 final. Frank Lampard's clear "ghost goal" for England against Germany in 2010 not being given (a key spur for goal-line technology). Geoff Hurst's contested "did it cross the line" goal in the 1966 final. Cambiasso's 24-pass team goal for Argentina in 2006. Roger Milla's corner-flag dance at 38 in 1990.`),
  k('kb-soc-numbers-lore', 'Shirt numbers and their meaning', ['shirt numbers meaning', 'number 10 playmaker', 'number 9 striker', 'number 7 winger', 'number 1 goalkeeper', 'squad numbers vs positional', 'retired numbers'], `Before squad numbers, teams wore 1-11 by position: 1 goalkeeper, 2 right-back, 3 left-back, 4 and 5 centre-backs, 6 defensive/left-sided midfielder, 7 right winger, 8 central midfielder, 9 centre-forward, 10 attacking midfielder / second striker, 11 left winger. The traditions stuck as symbols: the "number 10" means the creative talisman (Pele, Maradona, Messi, Zidane), the "number 9" the main striker, the "number 7" the flair wide man (Best, Ronaldo, Beckham). Since the 1990s players keep a fixed squad number for a season regardless of position. Clubs sometimes retire a number to honour a player (Napoli's 10 for Maradona, Milan's 6 for Baresi and 3 for Maldini, West Ham's 6 for Bobby Moore).`),

  // ===================== COMPETITIONS / STRUCTURE =====================
  k('kb-soc-league-pyramid', 'Promotion, relegation and the football pyramid', ['promotion and relegation', 'football pyramid', 'Championship', 'play-offs', 'no relegation MLS', 'open league system', 'parachute payments'], `Most of the world uses an OPEN league system: at the end of a season the bottom clubs of each division are RELEGATED to the division below and the top clubs of the lower division are PROMOTED up, so in theory a village club can climb to the top flight over many years (the "pyramid"). In England, the top 20 (Premier League) sit above the 72-club EFL (Championship, League One, League Two) and then the non-league game. The two or three automatic promotion spots are often supplemented by end-of-season PLAY-OFFS among the next few clubs. North American leagues (MLS) are CLOSED — franchises, no relegation, a draft and a salary cap, like other US sports. Relegation costs a club tens of millions in TV revenue, softened in England by temporary "parachute payments".`),
  k('kb-soc-cup-vs-league', 'Cup competitions versus league competitions', ['cup competition', 'knockout', 'FA Cup', 'Copa del Rey', 'DFB-Pokal', 'league round-robin', 'giant-killing', 'domestic double'], `A LEAGUE is a round-robin: every club plays every other twice (home and away) over a season, three points for a win, one for a draw, and the club with the most points is champion — it rewards consistency over ~34-38 games. A CUP is a single-elimination knockout: lose once and you are out, often with lower-division clubs drawn against giants ("giant-killing"), replays or extra time and penalties to separate teams, and a one-off final. The oldest is England's FA Cup (from 1871). Spain has the Copa del Rey, Germany the DFB-Pokal, Italy the Coppa Italia, France the Coupe de France. Winning the league and the main domestic cup in one season is "the Double"; adding the Champions League is "the Treble".`),
  k('kb-soc-continental-nations', 'Continental national-team tournaments', ['UEFA European Championship Euros', 'Copa America', 'AFCON Africa Cup of Nations', 'Asian Cup', 'CONCACAF Gold Cup', 'Nations League'], `Between World Cups, each confederation runs its own national-team championship. The UEFA European Championship ("the Euros"), held every four years, is second only to the World Cup in prestige (Spain are the most successful with four titles). South America's Copa America is the oldest international tournament (from 1916; Argentina and Uruguay lead). Africa's AFCON (Africa Cup of Nations) is held every two years, often in January, which clubs dislike because it takes their African stars mid-season. There are also the AFC Asian Cup, the CONCACAF Gold Cup, and the OFC Nations Cup. UEFA also runs the Nations League, a competitive replacement for friendlies that feeds into Euro qualifying.`),
  k('kb-soc-club-world-cup', 'FIFA Club World Cup and the Intercontinental Cup', ['FIFA Club World Cup', 'expanded 32-team 2025', 'Intercontinental Cup', 'European v South American champions', 'Copa Libertadores'], `The Club World Cup crowns the best club team in the world by bringing together the continental champions. The old annual seven-club format was usually won by the European (Champions League) holders, occasionally upset by a South American (Copa Libertadores) side. From 2025 FIFA expanded it to a 32-team tournament held every four years in the summer, modelled on the World Cup, with heavy prize money and criticism about player workload. Its ancestor was the Intercontinental Cup (1960-2004), a two-legged (later one-off) meeting of the European and South American champions.`),

  // ===================== BUSINESS / TRANSFERS =====================
  k('kb-soc-transfer-market', 'The transfer market and windows', ['transfer window', 'transfer fee', 'summer and winter window', 'deadline day', 'agent fees', 'sell-on clause', 'work permit'], `Player registrations can only be moved between clubs during official TRANSFER WINDOWS — a long one in the summer (roughly June to early September in Europe) and a short one in January. A permanent transfer involves a fee paid from the buying club to the selling club (unless the player's contract has expired — a "free transfer"), the player signing a new contract, and add-ons such as appearance/goal bonuses and a "sell-on clause" (the selling club gets a percentage of a future sale). Deals often run to the final minutes of "deadline day". Agents take large commissions, and non-EU players may need a work permit / points-based approval.`),
  k('kb-soc-record-transfers', 'Record transfers and the Neymar effect', ['Neymar 222 million', 'world record transfer', 'Mbappe', 'transfer fee inflation', 'PSG FFP', 'Bellingham Haaland fees', 'release clause'], `The world transfer record was broken repeatedly (Maradona, Zidane, Kaka, Ronaldo, Bale) but the biggest single leap was PSG paying Barcelona 222 million euros in 2017 to trigger Neymar's release clause — more than double the previous record. It reset the whole market's expectations, and 100 million euro deals became routine (Mbappe, Grealish, Enzo Fernandez, Moises Caicedo). A "release clause" (mandatory in Spain) is a pre-agreed price at which any club can sign a player without the selling club's consent. Financial rules (UEFA's Financial Fair Play, now the "squad-cost rule"; the Premier League's PSR) try to limit how much clubs can lose, with mixed success.`),
  k('kb-soc-loans-academy', 'Loans, academies and homegrown rules', ['loan system', 'development loan', 'buy option obligation', 'academy', 'homegrown player rule', 'category one academy', 'EPPP', 'training compensation'], `A LOAN temporarily sends a player to another club (keeping his registration with the parent club) for game time and development, or to offload wages; it can carry a fee, a wage split, and an option or obligation to buy. Big clubs run large loan armies (Chelsea historically). ACADEMIES develop players from childhood; a "homegrown" quota (in England, a minimum number of players trained domestically for three years before age 21) is meant to protect youth development, and clubs receive "training compensation" and solidarity payments when a player they raised is later transferred. La Masia (Barcelona), the Ajax academy, and Dortmund's talent identification are the most celebrated.`),
  k('kb-soc-ffp-ownership', 'Financial rules, ownership and state clubs', ['Financial Fair Play', 'PSR profitability and sustainability', 'squad cost ratio', 'state ownership Man City PSG Newcastle', 'Bosman ruling', '115 charges'], `UEFA's Financial Fair Play (2011), now reframed as a "squad-cost ratio" limiting spending on wages, transfers and agents to a share of revenue, and the Premier League's PSR (Profitability and Sustainability Rules, roughly a £105m loss limit over three years), aim to stop clubs spending themselves into crisis and to preserve competitive balance. They are controversial: they can entrench the existing elite and are hard to enforce (Manchester City face 115 charges; Everest and Nottingham Forest were docked points). State-linked ownership — Abu Dhabi at Manchester City, Qatar at PSG, Saudi Arabia's PIF at Newcastle — has changed the economics of the game. The 1995 Bosman ruling let players leave for free at contract end and abolished limits on EU players.`),

  // ===================== MISC =====================
  k('kb-soc-womens-football', 'Women\'s football', ['women\'s football', 'USWNT', 'Women\'s World Cup', 'Lionesses Euro 2022', 'Marta', 'equal pay', 'Women\'s Champions League'], `Women's football, long banned or unsupported by federations (England's FA banned it from grounds 1921-1971), has grown fast since the 1990s. The USA women's national team is the most successful, with four World Cups (1991, 1999, 2015, 2019) and a long fight for equal pay, finally settled in 2022. England's Lionesses won a home Euro 2022 in front of a record 87,000 at Wembley and reached the 2023 World Cup final (lost to Spain). Spain then won the 2023 World Cup amid a scandal over the federation president's unwanted kiss of a player. Marta (Brazil) is the all-time World Cup top scorer across both the men's and women's tournaments. The UEFA Women's Champions League (Lyon, then Barcelona dominant) mirrors the men's competition.`),
  k('kb-soc-analytics-xg', 'Football analytics and Expected Goals (xG)', ['expected goals xG', 'football analytics', 'data in football', 'xA expected assists', 'PPDA pressing intensity', 'progressive passes', 'Moneyball football'], `Data analysis has become central to recruitment and tactics. EXPECTED GOALS (xG) assigns every shot a probability of scoring (0 to 1) based on distance, angle, body part, assist type and defensive pressure, drawn from tens of thousands of past shots; adding a team's shot xGs gives a better measure of performance than the actual scoreline over time. Related metrics: xA (expected assists), PPDA (passes allowed per defensive action — lower means more intense pressing), progressive passes and carries, packing (opponents bypassed by a pass), and possession value models. Brentford and Brighton in England are known for data-led, "Moneyball" recruitment; almost every top club now has an analytics department.`),
  k('kb-soc-ball-kit-history', 'The ball, kits and equipment', ['football ball history', 'Adidas Telstar', 'Jabulani complaints', 'goal-line technology', 'shin pads', 'boots studs', 'kit numbers sponsors'], `The ball evolved from a heavy leather sphere (that soaked up water and could concuss headers) to synthetic, water-resistant, thermally bonded designs. Adidas has made the World Cup ball since 1970 (the black-and-white Telstar); the 2010 "Jabulani" was infamous for unpredictable flight. Goal-line technology (Hawk-Eye, GoalControl), introduced after England's disallowed 2010 goal, instantly signals to the referee's watch when the whole ball crosses the line. Players must wear shin pads; boots have moulded or screw-in studs chosen for the surface. Shirts carry a squad number, often the player's name, a club crest, a kit-manufacturer logo and a shirt sponsor (or a charity, as Barcelona long did with UNICEF).`),
  k('kb-soc-fan-culture', 'Fan culture: ultras, terraces and chants', ['ultras', 'curva', 'tifo displays', 'standing terraces', 'safe standing', 'Hillsborough', 'the twelfth man', 'away support'], `Organised support groups ("ultras" in Italy, Germany, South America and eastern Europe; "casuals" and the terrace culture in Britain) drive the atmosphere: coordinated singing, huge choreographed "tifo" banner displays, flares (usually illegal in the ground), and a home end nicknamed a "curva", "kop" or "wall". British grounds were forced all-seater after the 1989 Hillsborough disaster (97 Liverpool fans crushed to death due to police failures), though "safe standing" rail seating has since returned. Away fans are penned into an allocated section; a loud away following is prized. Fan culture also has a dark side — hooliganism, racism and pyrotechnic bans — that authorities continually police.`),
  k('kb-soc-nations-lore', 'International football lore', ['Brazil jogo bonito', 'Germany tournament team', 'Italy defensive', 'England 1966 penalty pain', 'Netherlands nearly men', 'Uruguay garra charrua'], `National footballing identities are real and enduring: Brazil ("jogo bonito", samba flair, five World Cups); Germany (relentless efficiency, four titles, "the ball is round and a game lasts 90 minutes"); Italy (defensive mastery, four titles, catenaccio); the Netherlands (Total Football beauty but three lost finals — the great "nearly men"); Argentina (Maradona, Messi, and passion); Uruguay (tiny country, two World Cups and "garra charrua" grit); Spain (decades of underachievement then tiki-taka dominance 2008-2012); and England (invented the game, one 1966 win at home, then decades of penalty-shootout heartbreak until reaching the 2018 semi and Euro 2020 final).`),
  k('kb-soc-poland-football', 'Polish football', ['Poland national team', 'Robert Lewandowski', 'Boniek Lato Deyna', '1974 1982 World Cup third place', 'Wembley 1973 The Clowns', 'Ekstraklasa Legia Lech'], `Poland's golden generation of the 1970s and early 80s — Grzegorz Lato (1974 World Cup Golden Boot), Kazimierz Deyna, Zbigniew Boniek, Wlodzimierz Lubanski — finished third at the 1974 and 1982 World Cups and won 1972 Olympic gold. Their 1973 draw at Wembley (goalkeeper Jan Tomaszewski, dubbed "a clown" by Brian Clough, kept England out of the 1974 World Cup) is legendary in Poland. Robert Lewandowski, one of the greatest pure number 9s ever (Dortmund, Bayern, Barcelona; the 2020 player who would have won the cancelled Ballon d'Or), has carried the national team for over a decade. Domestically the Ekstraklasa is led by Legia Warszawa, Lech Poznan, Wisla Krakow and Rakow Czestochowa.`),
  k('kb-soc-goal-celebrations', 'Goal celebrations and their rules', ['goal celebration', 'yellow card for removing shirt', 'knee slide', 'corner flag', 'siu Ronaldo', 'choreographed celebrations', 'celebrating in front of away fans'], `Scoring is followed by a celebration, but the Laws restrict it: removing your shirt, covering your head with it, climbing the perimeter fence, or making provocative/inflammatory gestures earn a yellow card, and time-wasting celebrations can too. Famous ones: Ronaldo's "Siu" leap and spin, Mbappe's arms-folded pose, Bebeto's baby-rocking (1994, celebrating a newborn), Klinsmann's diving celebration mocking his own reputation, Fabrizio Ravanelli pulling his shirt over his face, Icardi and others sliding on their knees, and elaborate team routines. Celebrating a goal in front of the opposition's fans, or against a former club, is often pointedly avoided — or pointedly not.`),
  k('kb-soc-managers-modern-tactics', 'Modern tactical trends', ['positional play vs relationism', 'build-up from the goalkeeper', 'rest defence', 'counterpress five seconds', 'box midfield', 'overloading the pivot', 'chance creation zone 14'], `Current elite trends: building attacks from the goalkeeper and centre-backs against a high press, using the keeper as an extra outfield player; structuring a "rest defence" (the players who stay back while others attack) to kill counter-attacks before they start; the five-second counter-press rule after losing the ball; "box midfield" shapes (two 6s and two 8s forming a square) to control the centre; inverted full-backs and centre-backs stepping into midfield; and building numerical superiority ("+1") in every zone the ball travels through. Against all this, low-block counter-attacking and long, direct set-piece-focused football (Brentford, some Simeone) remain effective antidotes.`),
  k('kb-soc-famous-stadiums', 'Famous stadiums', ['Camp Nou', 'Santiago Bernabeu', 'Maracana', 'Wembley', 'San Siro Giuseppe Meazza', 'Old Trafford', 'Anfield', 'Signal Iduna Park Yellow Wall'], `Iconic grounds: the Camp Nou / Spotify Camp Nou (Barcelona, Europe's biggest at ~99,000, mid-rebuild); the Santiago Bernabeu (Real Madrid, rebuilt with a retractable pitch and roof); the Maracana (Rio, host of two World Cup finals); Wembley (London, "the home of football", 90,000, the arch); the San Siro / Giuseppe Meazza (shared by Milan and Inter); Old Trafford ("the Theatre of Dreams", Manchester United); Anfield (Liverpool, "This Is Anfield" and "You'll Never Walk Alone"); Signal Iduna Park (Dortmund, whose "Yellow Wall" south terrace holds ~25,000 standing); La Bombonera (Boca Juniors, famously steep and loud); and Celtic Park.`),
  k('kb-soc-terminology', 'Common football terminology', ['nutmeg', 'brace hat-trick', 'clean sheet', 'parking the bus', 'route one', 'through ball', 'one-two wall pass', 'man on', 'time wasting', 'squeaky bum time'], `A quick glossary: NUTMEG (megs) — playing the ball through an opponent's legs; BRACE — two goals by one player, HAT-TRICK — three; CLEAN SHEET — conceding no goals; PARKING THE BUS — defending with all outfield players deep; ROUTE ONE — long direct balls to a target man; THROUGH BALL — a pass split between defenders for a runner; ONE-TWO / WALL PASS — pass and immediate return; MAN ON — a warning shout that an opponent is closing; PROFESSIONAL FOUL — a deliberate foul to stop an attack; SQUEAKY BUM TIME (Ferguson) — the tense end of a title race; SITTER — an easy chance missed; TAP-IN — an easy finish; WORLDIE — a spectacular goal; PANENKA — a chipped penalty down the middle.`),
  k('kb-soc-managers-history-list', 'Great national-team coaches', ['Vicente del Bosque', 'Joachim Low', 'Didier Deschamps', 'Lionel Scaloni', 'Carlos Bilardo', 'Aime Jacquet', 'Marcello Lippi', 'Luiz Felipe Scolari'], `World Cup-winning coaches worth knowing: Vittorio Pozzo (Italy, the only one to win twice as coach, 1934 and 1938); Mario Zagallo (Brazil, won as player and coach, part of four Brazilian wins); Franz Beckenbauer (West Germany 1990, also won as captain); Carlos Bilardo (Argentina 1986 with Maradona); Aime Jacquet (France 1998); Marcello Lippi (Italy 2006); Vicente del Bosque (Spain 2010, tiki-taka); Joachim Low (Germany 2014); Didier Deschamps (France 2018, also won as player); and Lionel Scaloni (Argentina 2022), a young former squad player who built a settled, Messi-centred team.`),
  k('kb-soc-clean-vs-shootout', 'Football scoring terms across countries', ['clean sheet vs shutout', 'brace', 'hat-trick match ball', 'own goal', 'goal difference', 'aggregate', 'nil', 'brace and perfect hat-trick'], `Terminology differs by country: a match with no goals conceded is a CLEAN SHEET (British) or a SHUTOUT (North American) — same thing. "Nil" (British) is "zero/nothing" (American): "two-nil". An OWN GOAL is a player scoring past his own keeper (credited to the attacking team). GOAL DIFFERENCE (goals for minus goals against) is the usual first league tiebreaker after points, then goals scored, then head-to-head. AGGREGATE is the combined score over a two-legged tie. A player scoring 2 has a BRACE, 3 a HAT-TRICK (and keeps the match ball), and a "perfect hat-trick" is one with the left foot, one with the right, one header.`),

  // ===================== GOALKEEPING (deep) =====================
  k('kb-soc-gk-technique', 'Goalkeeping technique and fundamentals', ['goalkeeper technique', 'set position', 'ready stance', 'W and scoop catch', 'diving save', 'narrowing the angle', 'catch versus parry', 'crosses claiming punching'], `Core goalkeeping technique: the SET POSITION (feet just wider than shoulders, weight on the balls of the feet, hands out in front, still at the instant the shot is struck). Handling: the "W" or "contour" catch for shots at chest height and above, the "scoop" or "cradle" for low shots and ground balls, always getting the body behind the ball where possible. Diving: push off the near foot, lead with the hands, land on the side (not the front), and try to catch or, if not, PARRY the ball wide of the goal and away from danger rather than straight back out. NARROWING THE ANGLE means advancing off the line toward the shooter to reduce the target; in a one-v-one, stay big, delay, and try to "spread" (make a star shape) as the attacker shoots. On crosses, decide early — claim it at the highest point with a loud call, or punch with two fists for distance and one fist through a crowd.`),
  k('kb-soc-gk-distribution', 'Goalkeeper distribution and playing out from the back', ['goalkeeper distribution', 'playing out from the back', 'goal kick short', 'rolling and throwing', 'drop kick half volley', 'splitting the press', 'goalkeeper as a passer'], `Modern goalkeepers are the first playmaker. Options: a fast, flat THROW (overarm javelin or roll) to start a quick counter to a full-back or winger; a SHORT PASS to a centre-back who has split wide for the goal kick; a DRIVEN or LOFTED KICK from hand or a placed ball to a target man or into space behind a high line; and the risky in-possession pass under press. Playing out from the back means the keeper and defenders deliberately invite the opponent's press and then break it with a well-timed pass into a free player between the lines, often the keeper stepping up as an extra outfielder to make a 3-v-2 against the first two pressers. It is high-reward (the opponent is now stretched and out of shape) and high-risk (a giveaway 20 metres from your own goal). Ederson, Alisson and Neuer are the benchmarks.`),
  k('kb-soc-gk-penalties', 'Goalkeepers and penalties / shootouts', ['goalkeeper penalty save', 'staying on the line one foot', 'diving early', 'reading the run-up', 'shootout psychology', 'Emiliano Martinez', 'saving to one side then the other'], `A goalkeeper facing a penalty must keep at least part of one foot on or in line with the goal line until the ball is kicked (a 2019 rule; encroachment can be a yellow card and a retake). Save tactics: watch the taker's run-up angle, plant foot direction and hips, decide a side and commit, or stay central against a chipper (Panenka). Many keepers "cheat" by moving a fraction early. In shootouts, psychology matters as much as technique — Emiliano Martinez (Argentina, 2021 Copa America and 2022 World Cup finals) is famous for slowing the process, talking to takers, gamesmanship and diving late; his saves and antics won two shootouts for Argentina. Statistically the taker still scores about 75% of the time, so a keeper who saves one or forces a miss is doing well.`),
  k('kb-soc-gk-legends', 'Legendary goalkeepers', ['Lev Yashin Black Spider', 'Gordon Banks save Pele 1970', 'Dino Zoff', 'Peter Schmeichel', 'Oliver Kahn', 'Gianluigi Buffon', 'Iker Casillas', 'Manuel Neuer', 'Edwin van der Sar'], `Lev Yashin (USSR): the "Black Spider", the only goalkeeper ever to win the Ballon d'Or (1963), credited with pioneering coming off the line and organising the defence. Gordon Banks (England): the 1966 World Cup winner and maker of "the save of the century" from a Pele header in 1970. Dino Zoff (Italy): oldest World Cup-winning captain, 1982, at 40. Peter Schmeichel (Denmark, Manchester United): huge, dominant, a "star jump" shot-stopper, key to the 1999 Treble. Oliver Kahn (Germany): ferociously intense, the only keeper to win the World Cup Golden Ball (2002). Then Buffon, Casillas, Van der Sar, Petr Cech, and Neuer, who redefined the position as a sweeper-keeper.`),
  k('kb-soc-gk-modern-role', 'The modern goalkeeper\'s job', ['modern goalkeeper role', 'sweeper keeper', 'high starting position', 'covering the space behind', 'shot-stopping still primary', 'distribution accuracy', 'command of the box', 'goalkeeper as leader'], `The 21st-century goalkeeper is judged on four things. SHOT-STOPPING is still primary — expected-goals-on-target models grade how many goals a keeper prevents versus an average keeper. DISTRIBUTION: pass completion under pressure, launching counters, being a genuine build-up option. COMMAND OF THE BOX: claiming crosses, dominating set pieces, communicating a defensive line. SWEEPING: starting 15-20 metres off the line so he can race out and clear through-balls before an attacker reaches them, letting the team defend a high line and press. The trade-offs are real — a keeper who sweeps aggressively concedes the occasional lob, and one who is asked to play out will occasionally be pressed into a mistake near his own goal. The best (Neuer, Ederson, Alisson, Donnarumma, Courtois) do all four.`),

  // ===================== MORE PLAYERS =====================
  k('kb-soc-ronaldinho', 'Ronaldinho', ['Ronaldinho', 'Barcelona 2003-2008', 'joga bonito', 'no-look pass', 'elastico flip-flap', '2005 Ballon d\'Or', 'Bernabeu standing ovation', 'bought Messi time'], `Ronaldinho Gaucho (Brazil) played for Paris Saint-Germain and then, most famously, Barcelona from 2003 to 2008, where he rebuilt a struggling club, won two La Ligas and the 2006 Champions League, and took the 2004 and 2005 FIFA World Player awards and the 2005 Ballon d'Or. He played with a permanent smile, all flair — the "elastico" (flip-flap), no-look passes, absurd free kicks — and in 2005 earned a standing ovation from Real Madrid's fans at the Bernabeu after a two-goal masterclass. He also mentored a teenage Lionel Messi in the dressing room. His level dropped sharply after 2007 through off-field indiscipline, but at his peak he was the most joyful footballer on earth.`),
  k('kb-soc-r9-ronaldo-nazario', 'Ronaldo Nazario ("R9", the original Ronaldo)', ['Ronaldo Nazario', 'R9', 'O Fenomeno', 'Brazil', 'Barcelona 96-97', 'Inter', 'Real Madrid', '2002 World Cup', 'knee injuries', 'stepover'], `Ronaldo Luis Nazario de Lima ("R9", "O Fenomeno") was, at his peak in 1996-1998, arguably the most devastating striker ever: blistering pace, power, close control at speed, and the stepover taken to another level. He scored 47 goals in his single Barcelona season (1996-97) at 20, then moved to Inter. A catastrophic knee injury and a mysterious convulsive fit before the 1998 World Cup final derailed years of his career, but he came back to win the 2002 World Cup, scoring both goals in the final and 8 in the tournament (Golden Boot), then joined Real Madrid's Galacticos. Two-time Ballon d'Or, three-time FIFA World Player, still the youngest winner of the latter at 20.`),
  k('kb-soc-benzema-suarez-lewandowski', 'Modern elite strikers: Benzema, Suarez, Lewandowski', ['Karim Benzema', '2022 Ballon d\'Or', 'Luis Suarez', 'biting incidents', 'Robert Lewandowski', 'record goalscoring Bayern', '5 goals in 9 minutes'], `Karim Benzema (France, Real Madrid): a "complete forward" who spent years as a selfless foil for Ronaldo, then carried Real Madrid to the 2022 Champions League with a run of hat-tricks and won the 2022 Ballon d'Or. Luis Suarez (Uruguay, Liverpool, Barcelona, Atletico): relentless, aggressive, a brilliant all-round centre-forward and part of Barca's MSN — also serially banned for biting opponents (three times) and a handball on the line at the 2010 World Cup. Robert Lewandowski (Poland, Dortmund, Bayern, Barcelona): a machine-like penalty-box finisher, scored 5 goals in 9 minutes for Bayern in 2015, broke Gerd Muller's Bundesliga single-season record with 41, and would have won the cancelled 2020 Ballon d'Or.`),
  k('kb-soc-defenders-legends', 'Legendary defenders', ['Franco Baresi', 'Paolo Maldini', 'Fabio Cannavaro', 'Sergio Ramos', 'Carles Puyol', 'Virgil van Dijk', 'Cafu Roberto Carlos', 'Bobby Moore'], `Paolo Maldini (Italy, AC Milan): played until 40 at the top level, 25 years at one club, a left-back and then centre-back of impeccable positioning and reading of the game. Franco Baresi (Milan): the definitive sweeper of Sacchi's pressing side. Fabio Cannavaro (Italy): a small centre-back who won the 2006 Ballon d'Or after captaining Italy to the World Cup. Sergio Ramos (Spain, Real Madrid): aggressive, a serial big-game scorer (the 93rd-minute header in the 2014 final), and the most-carded player in La Liga history. Carles Puyol (Barcelona): the heart of Guardiola's and Spain's defence. Virgil van Dijk (Netherlands, Liverpool): a modern dominant centre-back. Cafu and Roberto Carlos (Brazil): attacking full-backs who redefined the role.`),
  k('kb-soc-wingers-legends', 'Legendary wide players and dribblers', ['George Best', 'Garrincha', 'Ryan Giggs', 'Cristiano Ronaldo winger', 'Arjen Robben', 'Franck Ribery', 'Luis Figo', 'Gareth Bale', 'Eden Hazard'], `Garrincha (Brazil): "the Little Bird", a right-winger with bent legs and unplayable dribbling, arguably the difference in Brazil's 1962 World Cup win. George Best (Northern Ireland, Manchester United): genius and glamour in equal measure, the first footballing pop star. Ryan Giggs (Wales, Manchester United): 24 seasons of left-wing service and 13 league titles, scorer of a legendary solo FA Cup semi-final goal in 1999. Arjen Robben and Franck Ribery ("Robbery"): Bayern's wingers of the 2010s, Robben's inevitable cut-inside-and-curl and Ribery's trickery. Luis Figo: the winger whose 2000 move from Barcelona to Real Madrid is the most controversial transfer in the rivalry's history. Gareth Bale and Eden Hazard: pace-and-power and close-control archetypes of the recent era.`),
  k('kb-soc-modric-de-bruyne', 'Modric and De Bruyne: the modern deep creators', ['Luka Modric', '2018 Ballon d\'Or', 'Croatia 2018 final', 'Kevin De Bruyne', 'Manchester City assists record', 'raking diagonal pass', 'through balls'], `Luka Modric (Croatia, Tottenham, Real Madrid): a small, elegant central midfielder with a signature outside-of-the-boot pass, the engine of Real Madrid's four Champions Leagues in five years and of the Croatia side that reached the 2018 World Cup final, which won him the Ballon d'Or and broke the Messi-Ronaldo duopoly. Kevin De Bruyne (Belgium, Manchester City): rejected early by Chelsea, became the best chance-creating midfielder in the world at City under Guardiola — raking cross-field diagonals, whipped early crosses, and shots from distance — a repeat leader of the Premier League assists chart and central to the 2023 Treble.`),
  k('kb-soc-mbappe-haaland-deep', 'Mbappe and Haaland: the successor generation', ['Kylian Mbappe', 'PSG Real Madrid', '2018 World Cup 19', 'Erling Haaland', 'Manchester City goals record', 'contrasting striker types', 'pace versus power'], `Kylian Mbappe (France): explosive acceleration over the first ten metres, direct running from the left or through the middle, and elite finishing. He won the 2018 World Cup at 19 (scoring in the final), scored a hat-trick in the 2022 final in a losing effort, spent seven years dragging PSG through Ligue 1, and joined Real Madrid in 2024. Erling Haaland (Norway): 194 cm, freakishly fast for his size, and a pure box predator with either foot and his head. He broke the Bundesliga's goals-per-minute rates at Dortmund, then set a Premier League single-season record (36) in his first City year, winning the 2023 Treble. Between them they are the faces of the post-Messi/Ronaldo goalscoring era, one built on speed, the other on power.`),

  // ===================== MORE BARCA & SPAIN =====================
  k('kb-soc-barca-trophies', 'FC Barcelona honours and eras', ['Barcelona trophy list', '5 European Cups', '27 La Liga', 'Copa del Rey record', '3 Club World Cups', 'Cruyff Rijkaard Guardiola Enrique eras', 'sextuple 2009 treble 2015'], `Barcelona's major honours: 27 La Liga titles, a record 31+ Copa del Rey, 5 European Cup / Champions League (1992 Cruyff, 2006 Rijkaard, 2009 and 2011 Guardiola, 2015 Enrique), 5 UEFA Super Cups, 3 FIFA Club World Cups, and the unique 2009 sextuple. Distinct eras: the Cruyff "Dream Team" (1988-96), the Rivaldo/Figo years, the Ronaldinho revival (2003-06), the Guardiola peak (2008-12, "the best team ever" for many), the Luis Enrique MSN treble (2015), the decline and financial crisis (2018-2023, capped by the Roma and Liverpool collapses and Messi's forced exit), and the Xavi/Flick rebuild around La Masia youth.`),
  k('kb-soc-barca-crises', 'Barcelona\'s European collapses (2018-2020)', ['Roma 3-0 Barcelona 2018', 'Liverpool 4-0 Anfield 2019', 'Bayern 8-2 Barcelona 2020', 'Barca decline', 'Messi last years', 'squad ageing'], `Between the 2015 treble and Messi's exit, Barcelona suffered three brutal Champions League nights that defined their decline. 2018: 4-1 up on Roma from the first leg, they lost the second 3-0 and went out on away goals. 2019: 3-0 up on Liverpool from the first leg (Messi's free kick), they lost 4-0 at Anfield, the fourth goal from a quickly taken Trent Alexander-Arnold corner. 2020, in the COVID single-leg finals: an ageing, unbalanced side was hammered 8-2 by Bayern Munich in Lisbon — the heaviest defeat in the club's Champions League history and the moment that made the rebuild unavoidable.`),
  k('kb-soc-spain-tikitaka-era', 'Spain\'s golden generation (2008-2012)', ['Spain Euro 2008 2012 World Cup 2010', 'La Roja', 'tiki-taka', 'Xavi Iniesta Xabi Alonso Busquets', 'Del Bosque Aragones', 'only team to win three straight major tournaments'], `Spain, historically famous for underachieving, won three consecutive major tournaments: Euro 2008 (under Luis Aragones), the 2010 World Cup (Del Bosque, Iniesta's extra-time final goal), and Euro 2012 (a 4-0 final rout of Italy) — the only nation ever to do so. The core was the Barcelona spine (Xavi, Iniesta, Busquets, Pique) plus Xabi Alonso, Sergio Ramos, Iker Casillas and David Silva, playing suffocating possession football and, in 2012, even without a recognised striker (a "false nine" system). The cycle ended abruptly with a 5-1 group-stage loss to the Netherlands at the 2014 World Cup. Spain won again at Euro 2024 with a younger, more direct side featuring Rodri, Nico Williams and 16-year-old Lamine Yamal.`),
  k('kb-soc-camp-nou-espai', 'The Camp Nou and Espai Barca', ['Camp Nou history', 'Spotify Camp Nou', 'Espai Barca renovation', 'Montjuic temporary', 'largest stadium in Europe', '105000 capacity', 'the Cathedral'], `The Camp Nou opened in 1957 and is the largest stadium in Europe, previously ~99,000, sometimes called "the Cathedral". The club sold the naming rights to Spotify in 2022 as part of the "economic levers" to survive financially. The ground is being fully rebuilt ("Espai Barca") into a roofed ~105,000-seat stadium; during the works Barcelona played at the Olympic Stadium on Montjuic and then in a partially reopened Camp Nou. The pitch has hosted El Clasico, the 1992 Olympic football final, two Champions League finals, and Ronald Koeman's 1992 European Cup-winning free kick.`),

  // ===================== NATIONAL TEAMS / HISTORY =====================
  k('kb-soc-brazil-selecao', 'Brazil: the Selecao', ['Brazil national team', 'five World Cups', 'jogo bonito', '1970 team greatest ever', 'Pele Garrincha', 'Ronaldo Ronaldinho Rivaldo 3R', '7-1 Germany 2014', 'yellow shirt'], `Brazil are the most successful nation in World Cup history (5 titles: 1958, 1962, 1970, 1994, 2002) and the only one to appear at every tournament. The 1970 side (Pele, Jairzinho, Tostao, Gerson, Carlos Alberto) is widely called the greatest team ever assembled. The "jogo bonito" (beautiful game) identity — flair, skill, attacking freedom — is a national brand, though the 1994 and 2002 winners were more pragmatic. The lowest point was the 7-1 home semi-final humiliation by Germany in 2014, a national trauma. The iconic yellow-and-blue kit (the "Canarinho") replaced white after the 1950 Maracanazo defeat was blamed partly on the "unlucky" white shirts.`),
  k('kb-soc-germany-italy', 'Germany and Italy: the tournament nations', ['Germany four World Cups', 'die Mannschaft', 'tournament team', '2014 winners', 'Italy four World Cups', 'Azzurri', 'catenaccio', '2006 winners', 'missed 2018 and 2022'], `Germany (as West Germany and unified Germany) have won the World Cup four times (1954, 1974, 1990, 2014) and reached eight finals, with a reputation for peaking under pressure ("a tournament team") and for the 1954 "Miracle of Bern" upset of Hungary. The 2014 winners blended the 2000s youth-academy reform with tiki-taka influences. Italy have also won four times (1934, 1938, 1982, 2006), built on defensive organisation and clutch tournament football, and produced the greatest defenders and goalkeepers — yet failed to qualify for both the 2018 and 2022 World Cups, a stunning decline for a nation that had won Euro 2020 in between.`),
  k('kb-soc-argentina-france-england', 'Argentina, France and England', ['Argentina three World Cups', 'Maradona Messi', 'Albiceleste', 'France 1998 2018', 'Les Bleus diverse squad', 'England 1966', 'football coming home', 'penalty heartbreak'], `Argentina have won three World Cups (1978, 1986, 2022), the 1986 and 2022 wins built around a single generational talent (Maradona, then Messi). France have two (1998 at home under Jacquet, 2018 under Deschamps), with squads drawn heavily from the country's diverse suburbs and its elite Clairefontaine academy; they also lost the 2006 and 2022 finals. England, who codified the modern game, have won it once — at home in 1966 (Geoff Hurst's contested hat-trick against West Germany) — and endured decades of quarter-final exits and penalty-shootout losses before reaching the 2018 semi-final and the Euro 2020 final (lost on penalties at Wembley).`),
  k('kb-soc-african-football', 'African football and its legends', ['AFCON', 'George Weah', 'Didier Drogba', 'Samuel Eto\'o', 'Roger Milla', 'Mohamed Salah Sadio Mane', 'Yaya Toure', 'Morocco 2022 semi-final'], `African football's biggest names: George Weah (Liberia) — the only African to win the Ballon d'Or (1995), later President of Liberia. Roger Milla (Cameroon) — his corner-flag dances lit up Italia 90 at 38, when Cameroon became the first African side to reach a World Cup quarter-final. Didier Drogba (Ivory Coast) — Chelsea's decisive big-game striker and a peace figure in his home country's civil conflict. Samuel Eto'o (Cameroon) — a serial Champions League winner and AFCON top scorer. Yaya Toure, Michael Essien, Mohamed Salah, Sadio Mane, Riyad Mahrez. Morocco stunned the world by reaching the 2022 World Cup semi-final, the first African and first Arab nation to do so.`),
  k('kb-soc-copa-libertadores', 'The Copa Libertadores', ['Copa Libertadores', 'South American Champions League', 'Boca Juniors River Plate', 'Independiente seven titles', 'single-match final Lima', 'passion and chaos', 'Flamengo Palmeiras'], `The CONMEBOL Libertadores is South America's premier club competition, the equivalent of the Champions League, contested since 1960 by clubs from across the continent. Independiente (Argentina) hold the record with seven titles, ahead of Boca Juniors (6). Since 2019 the final is a single match at a neutral venue (mirroring UEFA) rather than two legs. It is famous for extreme fan atmospheres, long travel, altitude games in La Paz and Quito, and occasional chaos — the 2018 Boca-River final was moved to Madrid after River fans attacked the Boca team bus. Recent winners have often been Brazilian (Flamengo, Palmeiras, Fluminense), reflecting the financial gap that has grown between Brazil and the rest.`),

  // ===================== MORE COMPETITIONS / RULES =====================
  k('kb-soc-euros-history', 'The UEFA European Championship', ['Euros history', 'Euro 1992 Denmark', 'Euro 2004 Greece', 'Euro 2016 Portugal', 'Euro 2020 Italy', 'Euro 2024 Spain', 'expanded 24 teams', 'shock winners'], `The Euros, held every four years, is the world's second-biggest national-team tournament. Spain lead with four titles (1964, 2008, 2012, 2024). It is famous for shock winners: Denmark in 1992 (called up from their holidays after Yugoslavia were expelled for war), Greece in 2004 (a defensive, set-piece side that beat hosts Portugal twice), and Portugal in 2016 (grinding out results, winning the final without Ronaldo, who went off injured early). The tournament expanded from 16 to 24 teams in 2016. Euro 2020, delayed a year by COVID and played across 11 cities, was won by Italy on penalties against England at Wembley.`),
  k('kb-soc-ffp-psr-detail', 'Financial Fair Play, PSR and points deductions', ['Financial Fair Play', 'break-even requirement', 'PSR 105 million', 'squad cost ratio 70 percent', 'Everton Nottingham Forest points deduction', 'Manchester City 115 charges', 'Juventus'], `UEFA's Financial Fair Play (2011) required clubs to roughly "break even" over a rolling period; it is being replaced by a "squad-cost ratio" capping spending on wages, transfer amortisation and agents at 70% of football revenue. The Premier League's PSR allows a maximum loss of about £105 million over three seasons. Enforcement produced real punishments in 2023-24: Everton and Nottingham Forest were docked points, Juventus were docked points in Serie A for accounting over transfer fees, and Manchester City face 115 charges of breaching financial rules over nearly a decade (case ongoing). Critics say the rules lock in the historical big clubs and are inconsistently applied.`),
  k('kb-soc-subs-added-time', 'Substitutions and added time rules', ['five substitutions', 'concussion substitute', 'three windows', 'added time crackdown', 'time wasting', '2022 World Cup long added time', 'ball in play'], `Since 2020 (made permanent after COVID) teams may make FIVE substitutions per match, but only in THREE windows plus half-time, to stop games being broken up. Additional concussion substitutions are allowed on top. From the 2022 World Cup, referees were told to add MUCH more stoppage time — precisely accounting for goal celebrations, substitutions, injuries, VAR checks and deliberate time-wasting — leading to games with 10-15 minutes added. The aim is to increase actual "ball in play" time, which had fallen to under 55 minutes in many matches. Persistent time-wasting by a leading team is now more readily punished with yellow cards.`),
  k('kb-soc-dogso-advantage-detail', 'DOGSO, SPA and the advantage rule', ['denying an obvious goalscoring opportunity', 'DOGSO red card', 'triple punishment', 'stopping a promising attack SPA yellow', 'advantage rule', 'referee signals play on'], `DOGSO (Denying an Obvious Goalscoring Opportunity) is a red-card offence — a foul or deliberate handball that stops a clear chance, judged on the distance to goal, the direction of play, the number of defenders, and the likelihood of keeping or controlling the ball. Since 2016 a DOGSO foul inside the penalty area where the defender was genuinely attempting to play the ball is downgraded to a yellow (ending the old "triple punishment" of penalty + red + suspension). SPA (Stopping a Promising Attack) is a lesser version — a cynical foul that ends a dangerous move that was not yet a clear chance — and is a yellow card. The ADVANTAGE rule lets the referee wave play on after a foul if the fouled team keeps a good attacking position, coming back for the card at the next stoppage.`),
  k('kb-soc-transfers-loans-detail', 'The mechanics of transfers and loans', ['transfer fee amortisation', 'signing on fee', 'agent commission', 'buy-back clause', 'obligation to buy', 'loan with option', 'homegrown quota', 'FIFA clearing house'], `A transfer fee is paid to the selling club; in the buyer's accounts it is "amortised" (spread) over the length of the new contract, which is why clubs give long contracts to soften the annual cost. Players also receive a signing-on fee and wages, and agents take a commission (often 5-10%, sometimes paid by both sides). Common clauses: a SELL-ON percentage of a future transfer to the original club; a BUY-BACK clause letting the seller re-sign the player at a set price; and, on loans, an OPTION to buy (the loan club may sign him for an agreed fee) or an OBLIGATION to buy (it must, if conditions like appearances or survival are met). FIFA now runs a clearing house to route training-compensation and solidarity payments to the clubs that developed young players.`),

  // ===================== MORE TACTICS / MICRO-CONCEPTS =====================
  k('kb-soc-transitions', 'Transitions: the four moments of the game', ['four phases of play', 'in possession out of possession', 'attacking transition', 'defensive transition', 'counter-attack', 'counter-press', 'rest defence'], `Modern coaching splits the game into four moments: IN POSSESSION (organised attack), OUT OF POSSESSION (organised defence), ATTACKING TRANSITION (the seconds just after you win the ball — attack fast before the opponent reorganises, or slow it down to keep it), and DEFENSIVE TRANSITION (the seconds just after you lose it — either counter-press immediately to win it back, or drop quickly into shape). Elite matches are often decided in the transition moments, because both teams are temporarily out of structure. The "rest defence" — the shape of the players who stay back while others attack — exists specifically to control the defensive transition and snuff out counter-attacks before they begin.`),
  k('kb-soc-build-up-phases', 'Phases of possession: build-up, progression, finishing', ['build-up phase', 'first phase', 'progression phase', 'final third', 'breaking lines', 'between the lines', 'creating the final pass', 'penetration'], `Coaches describe an attack in phases. BUILD-UP (first phase): playing out from the goalkeeper and centre-backs against the opponent's forward press, aiming to reach midfield with the ball and numbers intact. PROGRESSION (second phase / middle third): breaking the opponent's midfield line — a pass into a player "between the lines", a carry through a gap, a switch of play to the free side. FINISHING (third phase / final third): creating and taking a chance — the "final pass", a cross, a cutback, a shot from zone 14, an overlap-and-cross, a set piece won. Teams can be excellent in one phase and poor in another (great build-up, blunt in the final third, or vice versa).`),
  k('kb-soc-marking-systems', 'Marking systems and defensive structure', ['man marking', 'zonal marking', 'hybrid marking', 'pressing traps', 'defensive line height', 'compactness', 'covering shadow', 'jockeying'], `A defence must decide, for open play and for set pieces, how it picks up attackers: MAN MARKING (follow a specific opponent everywhere), ZONAL MARKING (defend a space and challenge any ball in it), or a HYBRID. It must also set the LINE HEIGHT (high to compress the pitch and press, deep to protect space behind) and stay COMPACT (short distances between the lines so there is nowhere to play through). A defender pressing an opponent uses his "covering shadow" — his body position blocks a passing lane while he closes down. One-v-one, a defender "jockeys": staying on his feet, showing the attacker one way, delaying rather than diving in. A pressing trap deliberately leaves a pass open (usually to a full-back) and then swarms it.`),
  k('kb-soc-width-depth-tempo', 'Width, depth, tempo and rotations', ['pitch width', 'stretching the defence', 'depth runs in behind', 'tempo of possession', 'third-man combinations', 'positional rotations', 'overloads', 'underlaps'], `Attacking principles: WIDTH (keep players on both touchlines to stretch the defence horizontally so gaps open centrally); DEPTH (have runners threatening the space in behind, so the defence cannot push up and squeeze); TEMPO (mix slow, patient circulation to move the opponent with sudden fast, vertical passes to punish a gap); ROTATIONS (players swap positions — a winger comes inside, a full-back overlaps into his space, a midfielder drops — to disorganise markers); OVERLOADS (create a 3-v-2 in one area to free a man); UNDERLAPS (a full-back or midfielder runs inside the winger rather than outside). Guardiola's rule of thumb: no more than three players in the same horizontal line and no more than two in the same vertical channel.`),
  k('kb-soc-park-the-bus-low-block', 'The low block and "parking the bus"', ['park the bus', 'low block defending', 'two banks of four', 'deep defensive shape', 'time wasting when ahead', 'frustrating a possession team', 'Mourinho Simeone'], `A LOW BLOCK is a compact defensive shape set up deep in a team's own third — typically two banks of four (or a five and a four) close together, denying space between and behind the lines, forcing the opponent to shoot from distance or cross into a crowded box. "Parking the bus" is the extreme, cynical version — every outfield player behind the ball, minimal attacking intent, often when protecting a lead or facing a much stronger side. It is genuinely effective against dominant possession teams that have no pace in behind to exploit, and is a hallmark of many Mourinho and Simeone big-game plans, but a full 90 minutes of it invites relentless pressure and one moment of quality or a set piece can undo it.`),
  k('kb-soc-pressing-traps', 'Pressing triggers and traps', ['pressing trigger', 'pressing trap', 'showing inside or outside', 'forcing the play one way', 'trap the full-back', 'counterpress on turnover', 'press resistance'], `A coordinated press needs TRIGGERS — cues for the whole team to jump: a heavy or backward touch by an opponent, a pass to a player facing his own goal, a ball played toward the touchline (which acts as an extra defender), or a specific weak passer receiving. A pressing TRAP deliberately leaves one option open — commonly a full-back near the sideline — and as the ball travels there the nearest players collapse on him from three sides while cover shifts across, aiming to win the ball high in a dangerous area. "Press resistance" is a player's ability to keep the ball under this pressure — a good first touch away from the presser, a body feint, a quick lay-off to a teammate — which is why press-resistant midfielders (Busquets, Rodri) are so valued.`),

  // ===================== MORE RECORDS / LORE / MISC =====================
  k('kb-soc-most-titles-clubs', 'The most decorated clubs', ['Real Madrid most Champions Leagues', 'Rangers Celtic domestic titles', 'Al Ahly most Club World Cup appearances', 'Linfield Rangers world record league titles', 'most trophies'], `Some club records: Real Madrid have the most European Cup / Champions League titles (15). For domestic league titles, the world record holders are clubs from smaller leagues — Rangers and Celtic (Scotland) and Linfield (Northern Ireland) each with well over 50. In the "big five" leagues: Juventus (36 Serie A), Real Madrid (36 La Liga), Bayern Munich (33 Bundesliga), Manchester United (20 English titles), Saint-Etienne and PSG lead in France. Al Ahly (Egypt) have a record number of CAF Champions League titles. The most trophies won by any club in a single calendar year is Barcelona's six in 2009.`),
  k('kb-soc-underdog-runs', 'Great underdog and cup runs', ['Wimbledon Crazy Gang 1988 FA Cup', 'Greece Euro 2004', 'Denmark Euro 1992', 'Leicester 2016', 'Nottingham Forest back-to-back European Cups', 'Porto 2004', 'Wrexham'], `Football's great underdog stories: Nottingham Forest, promoted from the Second Division, won the English title and then back-to-back European Cups (1979, 1980) under Brian Clough. Wimbledon's "Crazy Gang", a decade after being non-league, beat Liverpool to win the 1988 FA Cup. Denmark's 1992 and Greece's 2004 European Championship wins. Porto winning the 2004 Champions League under a young Mourinho. Leicester City's 2016 Premier League. Non-league Sutton and Lincoln reaching FA Cup quarter-finals. Wrexham, the world's third-oldest professional club, bought by Hollywood actors and climbing back up the English pyramid with a Netflix documentary attached.`),
  k('kb-soc-goal-of-century-lists', 'Contenders for the greatest goal ever', ['Maradona goal of the century 1986', 'Carlos Alberto 1970', 'Weah solo goal 1996', 'Roberto Carlos banana free kick', 'Zidane 2002 volley', 'Ibrahimovic bicycle vs England', 'Messi vs Getafe'], `Regularly cited as the greatest goals: Diego Maradona's 60-metre slalom past five England players (1986 World Cup); Carlos Alberto finishing Brazil's team move in the 1970 final; George Weah's full-pitch solo run for Milan (1996); Roberto Carlos's impossible swerving free kick against France (1997); Zinedine Zidane's left-foot volley for Real Madrid in the 2002 Champions League final; Zlatan Ibrahimovic's 30-yard bicycle kick against England (2012); Lionel Messi's near-replica of Maradona's goal against Getafe (2007); and Dennis Bergkamp's spin-and-finish against Newcastle (2002).`),
  k('kb-soc-injuries-fitness', 'Common football injuries and load management', ['ACL injury', 'hamstring strain', 'muscle injuries fixture congestion', 'load management', 'sports science', 'return to play', 'GPS monitoring'], `The most feared football injury is a torn anterior cruciate ligament (ACL) in the knee, which costs 6-12 months and can permanently reduce a player's sharpness. The most common are muscle injuries, especially hamstring strains, driven by sprinting load and fixture congestion. Clubs now run large sports-science departments: GPS vests monitor sprint distances and accelerations in training and matches, and coaches manage "load" (rotating players, cutting sprint volume before games) to reduce soft-tissue injuries. The debate about too many matches — expanded Club World Cup, longer added time, deep cup runs plus internationals — has become a central issue, with player unions warning about burnout.`),
  k('kb-soc-panini-media', 'Football media, stickers and video games', ['Panini World Cup stickers', 'got got need', 'FIFA EA Sports FC video game', 'Football Manager', 'ultimate team packs', 'gambling and loot boxes'], `Football's cultural footprint beyond the pitch: Panini sticker albums, a World Cup tradition since 1970 ("got, got, need"), turned into a global collecting craze and a debate about their cost. The EA Sports FIFA video game (rebranded EA Sports FC in 2023 after the FIFA licence split) is one of the best-selling franchises in gaming, with its "Ultimate Team" card-pack mode drawing scrutiny for resembling gambling. Football Manager is the definitive management simulation, so detailed that real clubs have used its database for scouting. Broadcast rights are the sport's biggest revenue source, and the calendar and kick-off times are increasingly shaped by overseas TV audiences.`),
  k('kb-soc-womens-game-growth', 'The growth of the women\'s game', ['Women\'s Super League', 'NWSL', 'Women\'s Champions League Barcelona Lyon', 'Alexia Putellas', 'Aitana Bonmati', 'record attendances', 'professionalisation'], `Women's club football has professionalised rapidly. England's Women's Super League and the US NWSL are the strongest domestic leagues; the UEFA Women's Champions League has been dominated first by Lyon and then by FC Barcelona Femeni, who set a world attendance record of over 91,000 at the Camp Nou in 2022. Barcelona's Alexia Putellas and Aitana Bonmati have won recent women's Ballon d'Or awards. The 2019 and 2023 Women's World Cups drew record global audiences, and the game is now a serious commercial property with its own broadcast deals, though pay and facilities still lag far behind the men's game.`),
  k('kb-soc-referee-var-controversies', 'Refereeing and VAR controversies', ['VAR controversy', 'offside by a toe', 'handball interpretation', 'subjective calls', 'Premier League PGMOL', 'audio released', 'referee abuse'], `VAR was meant to end clear injustices but has created its own arguments: offside decisions given for a toe or shoulder with drawn lines and a chosen "kick point"; inconsistent handball rulings; long delays that kill the flow and the celebration; and the fact that VAR only corrects "clear and obvious" errors, so a bad-but-defensible on-field call often stands. High-profile mistakes (a wrongly disallowed Luis Diaz goal for Liverpool in 2023, with the referees' audio later released) have fuelled distrust. Referee abuse — online, from managers, and in the grassroots game — has become a serious problem, and bodies like England's PGMOL now publish more explanation of decisions to rebuild trust.`),
  k('kb-soc-super-league-collapse', 'The failed European Super League', ['European Super League 2021', 'breakaway 12 clubs', 'fan backlash', 'closed competition no relegation', 'UEFA FIFA opposition', 'A22 court ruling'], `In April 2021, twelve of Europe's biggest clubs (including Real Madrid, Barcelona, Juventus, Manchester United, Liverpool, Arsenal and Chelsea) announced a breakaway "European Super League" — a largely closed midweek competition with permanent founding members and no promotion/relegation, designed to guarantee their revenues. It collapsed within 72 hours under a wall of fan protests, government threats, player and manager opposition, and pressure from UEFA and FIFA. The English clubs pulled out first. Real Madrid and Barcelona kept pursuing it through the courts; a 2023 EU ruling said UEFA's blanket ban on rival competitions could breach competition law, but no viable Super League has emerged, and fan hostility to a closed elite remains intense.`),
  k('kb-soc-boot-room-culture', 'Club identity, the boot room and continuity', ['Liverpool boot room', 'Ajax academy philosophy', 'Athletic Bilbao Basque policy', 'club DNA', 'director of football model', 'sporting director', 'coaching continuity'], `Successful clubs often have a defined identity that outlasts individual managers. Liverpool's "boot room" was a literal room where coaches (Shankly, Paisley, Fagan, Moran) shared ideas and promoted from within, giving decades of continuity. Ajax and Barcelona impose one playing philosophy from the under-9s up so any academy graduate fits the first team. Athletic Bilbao only sign players of Basque origin or training, a self-imposed limit they have never dropped. The modern structure separates the head coach (short-term, results, on-pitch) from a sporting director / director of football (long-term recruitment, academy, style), so a change of coach does not mean starting from zero.`),
  k('kb-soc-corner-throw-routines', 'Corner and free-kick routines in detail', ['corner routine', 'near post flick on', 'inswinger outswinger', 'zone marking corner', 'short corner', 'blocking runs pick', 'attacking the goalkeeper', 'training ground routine'], `An INSWINGING corner curls toward goal (dangerous, can be flicked in or turned in by the keeper); an OUTSWINGER curls away, easier to attack with a run. Common attacking routines: a near-post RUNNER to flick the ball on across goal for arriving players; a "screen" or "pick" where an attacker legally blocks a marker to free the target; overloading the six-yard box to occupy the keeper; a short corner to open the angle for a cross or a shot; and a decoy crowd at the near post with the real target hanging at the back. Defensively, teams choose zonal (each player owns a spot), man (each marks a runner) or hybrid, plus a man on each post in some systems, and try to attack the ball high and clear it long.`),
  k('kb-soc-goal-line-tech-semi-auto', 'Technology in football: GLT and semi-automated offside', ['goal-line technology', 'Hawk-Eye', 'GoalControl', 'semi-automated offside', 'limb tracking', 'connected ball', 'referee smartwatch alert'], `GOAL-LINE TECHNOLOGY (GLT), used since the 2014 World Cup, employs 7-14 high-speed cameras per goal (Hawk-Eye) or magnetic-field sensors to determine within a second whether the whole ball crossed the whole line, sending an instant "GOAL" alert to the referee's watch — no human judgement, no debate. SEMI-AUTOMATED OFFSIDE, used from the 2022 World Cup and the Champions League, tracks up to 29 points on each player's body 50 times a second, plus a sensor inside the match ball that records the exact kick moment, to generate an offside decision and a 3D animation for broadcast in seconds, cutting the long manual VAR line-drawing.`),
  k('kb-soc-managerial-styles', 'Managerial archetypes', ['tracksuit manager coach', 'tactical innovator', 'man-manager motivator', 'chairman-style manager', 'the tinkerman', 'firefighter relegation specialist', 'club builder'], `Rough manager archetypes: the TACTICAL INNOVATOR who imposes a distinctive system (Guardiola, Bielsa, Sacchi); the MAN-MANAGER / MOTIVATOR who gets more out of a squad than the sum of its parts (Ferguson, Ancelotti, Klopp's energy); the PRAGMATIST who wins with structure and big-game plans regardless of style (Mourinho, Simeone); the "TINKERMAN" who constantly rotates and changes shape (Ranieri, Tuchel); the FIREFIGHTER / relegation specialist brought in mid-season to steady a sinking club (Sam Allardyce, Tony Pulis); and the CLUB BUILDER who develops youth and infrastructure over years (Wenger's early Arsenal, Nagelsmann's rise). Most top managers blend several of these.`),
  k('kb-soc-fitness-positions', 'Physical demands by position', ['distance covered per match', 'high-speed running', 'goalkeeper low distance high intensity', 'midfielder most distance', 'full-back sprint load', 'striker acceleration', 'GPS data'], `GPS data shows big differences by role. Central midfielders cover the most ground, often 11-13 km a match, much of it jogging and repositioning. Full-backs and wide players cover slightly less total distance but the most HIGH-SPEED running and sprints, because they repeatedly overlap and recover. Centre-backs cover less ground but with frequent short, explosive accelerations and jumps. Strikers do a lot of high-intensity but stop-start work — pressing, spinning in behind. Goalkeepers cover by far the least (~5 km) but with intense, unpredictable dives, jumps and rapid changes of direction, and a very high mental load. This is why fitness and recovery are periodised differently for each position.`),
  k('kb-soc-set-piece-specialists', 'Free-kick and penalty specialists', ['free kick technique', 'knuckleball', 'curl over the wall', 'Juninho Pernambucano', 'Cristiano Ronaldo free kicks', 'Messi curled free kicks', 'penalty takers', 'the Panenka'], `Direct free-kick styles: the CURLED effort over and around the wall into the top corner (Messi, Beckham, Juninho Pernambucano — the acknowledged master); the KNUCKLEBALL / dip, struck with minimal spin so it swerves late and unpredictably (Cristiano Ronaldo, Juninho, Pirlo); and the driven low effort under a jumping wall. Penalty approaches: pick a corner and hit it hard and accurately regardless of the keeper; wait for the keeper to move and go the other way ("keeper-dependent"); or the PANENKA — a delicate chip straight down the middle as the keeper dives, high-risk and humiliating if the keeper stays. Clubs identify a set order of penalty takers and practise shootouts, though pressure in a real shootout is hard to simulate.`),
  k('kb-soc-glossary-2', 'More football terminology', ['tifo', 'derby day', 'six-pointer', 'relegation dogfight', 'top-four race', 'squad depth', 'game state', 'hospital pass', 'ghosting in', 'against the run of play'], `More terms: SIX-POINTER — a match between two direct rivals for a position, worth extra because a win also denies the opponent; RELEGATION DOGFIGHT / SCRAP — the tense battle among the bottom clubs; GAME STATE — the current scoreline and its effect on how teams play (a team leading sits deeper); AGAINST THE RUN OF PLAY — a goal by the team that was being outplayed; HOSPITAL PASS — a pass that leaves a teammate about to be hit hard by an opponent; GHOSTING IN — a player arriving unmarked at the back post; PARK THE BUS — see the low-block entry; FALSE DAWN — a good result that turns out not to signal real improvement; BOTTLING IT — losing a strong position through nerves.`),
  k('kb-soc-conmebol-uefa-gap', 'Why European clubs dominate world football', ['European clubs richest', 'South American talent drain', 'transfer economics', 'Champions League money', 'players leave at 18', 'Club World Cup European wins', 'financial gap'], `Since the 1990s, European clubs have pulled far ahead of the rest of the world financially, driven by huge domestic and Champions League TV deals. The consequence is a talent drain: the best South American, African and Asian teenagers are signed by European clubs at 16-18, so the strongest national leagues elsewhere become development and export markets. This is why the Club World Cup has almost always been won by the European entrant, why the Champions League is effectively the world championship of clubs, and why calls for a redistributed global calendar and revenue-sharing keep resurfacing. Brazilian clubs have recently closed some of the gap through their own growing TV and sponsorship money.`),
  k('kb-soc-famous-managers-quotes', 'Football culture: famous lines', ['football bloody hell Ferguson', 'game of two halves', 'the boy done good', 'we go again', 'it is what it is', 'squeaky bum time', 'park the bus Mourinho', 'nobody remembers who came second'], `Football's cliches and famous lines are part of its culture: Sir Alex Ferguson's "Football, bloody hell" after the 1999 final; Bill Shankly's (possibly apocryphal) "some people think football is a matter of life and death... it is much more important than that"; "a game of two halves"; "the league table doesn't lie"; Mourinho popularising "park the bus" as a complaint about Tottenham; Arsene Wenger's "I did not see it" about incidents involving his own players; "we go again" (relentless positivity after a defeat); and the pundit's "for me, Clive". Commentary landmarks include Kenneth Wolstenholme's "they think it's all over... it is now!" (1966) and "Agueroooo" (2012).`),
];
